screenPanels.initJs:
function(container, apiUrl, tables) {
  let salesChart = null;
  let weatherChart = null;

  // データ更新関数
  async function updateDashboard() {
    try {
      container.querySelector("#error-message").classList.add("hidden");

      const selectedStore = container.querySelector("#store-select").value;
      const selectedPeriod = parseInt(container.querySelector("#period-select").value);

      // 各テーブルからデータを取得
      const salesData = await window.aivicApi.list(3) || []; // 売上実績データ
      const forecastData = await window.aivicApi.list(9) || []; // 需要予測結果
      const orderData = await window.aivicApi.list(10) || []; // 発注データ
      const productData = await window.aivicApi.list(2) || []; // 商品マスタ
      const weatherData = await window.aivicApi.list(4) || []; // 天候データ
      const eventData = await window.aivicApi.list(5) || []; // イベントデータ

      // 期間フィルタリング
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - selectedPeriod);

      const filteredSales = salesData.filter(s => {
        if (selectedStore && s.店舗ID !== selectedStore) return false;
        return new Date(s.売上日) >= cutoffDate;
      });

      // KPI計算
      updateKPIs(filteredSales, forecastData, orderData);

      // グラフ更新
      updateSalesTrendChart(filteredSales);
      updateWeatherChart(weatherData, filteredSales);

      // ランキング更新
      updateProductRanking(filteredSales, productData);

      // ステータス更新
      updateOrderStatus(orderData);

      // アラート更新
      updateInventoryAlerts(filteredSales, productData);

      // イベント更新
      updateEventFactors(eventData);

    } catch (error) {
      console.error("Dashboard update error:", error);
      container.querySelector("#error-message").classList.remove("hidden");
    }
  }

  // KPI更新
  function updateKPIs(salesData, forecastData, orderData) {
    // 売上実績
    const totalSales = salesData.reduce((sum, s) => sum + (s.売上金額 || 0), 0);
    container.querySelector("#kpi-sales").textContent = `¥${totalSales.toLocaleString()}`;

    // 需要予測精度（MAPE計算）
    const accuracyData = forecastData.filter(f => f.実績数量 && f.予測数量);
    let avgAccuracy = 0;
    if (accuracyData.length > 0) {
      const mape = accuracyData.reduce((sum, f) => {
        return sum + Math.abs((f.実績数量 - f.予測数量) / f.実績数量);
      }, 0) / accuracyData.length;
      avgAccuracy = Math.max(0, 100 - (mape * 100));
    }
    container.querySelector("#kpi-accuracy").textContent = `${avgAccuracy.toFixed(1)}%`;

    // 発注件数
    const orderCount = orderData.length;
    container.querySelector("#kpi-orders").textContent = `${orderCount}件`;

    // 在庫アラート（仮の計算）
    const alertCount = Math.floor(salesData.length * 0.1);
    container.querySelector("#kpi-alerts").textContent = `${alertCount}件`;
  }

  // 売上トレンドグラフ
  function updateSalesTrendChart(salesData) {
    const ctx = container.querySelector("#sales-trend-chart").getContext("2d");

    // 日別集計
    const dailySales = {};
    salesData.forEach(s => {
      const date = s.売上日?.slice(0, 10) || new Date().toISOString().slice(0, 10);
      dailySales[date] = (dailySales[date] || 0) + (s.売上金額 || 0);
    });

    const sortedDates = Object.keys(dailySales).sort();
    const labels = sortedDates.map(d => d.slice(5)); // MM-DD形式
    const data = sortedDates.map(d => dailySales[d]);

    if (salesChart) {
      salesChart.destroy();
    }

    salesChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '売上金額',
          data: data,
          borderColor: '#4a90e2',
          backgroundColor: 'rgba(74, 144, 226, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // 天候影響分析チャート
  function updateWeatherChart(weatherData, salesData) {
    const ctx = container.querySelector("#weather-chart").getContext("2d");

    // 気温別売上集計
    const tempSales = {};
    salesData.forEach(s => {
      const temp = s.気温 || 20;
      const tempRange = Math.floor(temp / 5) * 5; // 5度刻み
      tempSales[tempRange] = (tempSales[tempRange] || 0) + (s.売上金額 || 0);
    });

    const temps = Object.keys(tempSales).sort((a, b) => a - b);
    const labels = temps.map(t => `${t}°C~`);
    const data = temps.map(t => tempSales[t]);

    if (weatherChart) {
      weatherChart.destroy();
    }

    weatherChart = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [{
          label: '売上金額',
          data: data,
          backgroundColor: '#7cb342'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // 商品別売上ランキング
  function updateProductRanking(salesData, productData) {
    const productSales = {};
    salesData.forEach(s => {
      productSales[s.商品ID] = (productSales[s.商品ID] || 0) + (s.売上金額 || 0);
    });

    const ranking = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10);

    const html = ranking.map(([productId, sales], index) => {
      const product = productData.find(p => p.商品ID === productId);
      const productName = product?.商品名 || `商品${productId}`;
      return `
        <div class="ranking-item">
          <span class="rank">${index + 1}</span>
          <span class="product-name">${productName}</span>
          <span class="sales-amount">¥${sales.toLocaleString()}</span>
        </div>
      `;
    }).join("");

    container.querySelector("#product-ranking").innerHTML = html || '<div class="ranking-item"><span class="product-name">データがありません</span></div>';
  }

  // 発注状況ステータス
  function updateOrderStatus(orderData) {
    const statusCounts = {
      pending: 0,
      ordered: 0,
      received: 0
    };

    orderData.forEach(o => {
      const status = o.発注ステータス || '未発注';
      if (status.includes('未発注')) statusCounts.pending++;
      else if (status.includes('発注済')) statusCounts.ordered++;
      else if (status.includes('納品済')) statusCounts.received++;
    });

    container.querySelector("#status-pending").textContent = statusCounts.pending;
    container.querySelector("#status-ordered").textContent = statusCounts.ordered;
    container.querySelector("#status-received").textContent = statusCounts.received;
  }

  // 在庫アラート
  function updateInventoryAlerts(salesData, productData) {
    const alerts = [];

    // 売上の多い商品で在庫切れフラグがある場合をアラートとする
    const productSales = {};
    salesData.forEach(s => {
      if (s.在庫切れフラグ) {
        productSales[s.商品ID] = (productSales[s.商品ID] || 0) + (s.売上金額 || 0);
      }
    });

    Object.entries(productSales).slice(0, 5).forEach(([productId, sales]) => {
      const product = productData.find(p => p.商品ID === productId);
      const productName = product?.商品名 || `商品${productId}`;
      alerts.push({
        level: 'warning',
        message: `${productName} - 在庫不足が発生しています`
      });
    });

    const html = alerts.length > 0 ? alerts.map(alert => `
      <div class="alert-item">
        <span class="alert-level ${alert.level}">${alert.level === 'warning' ? '警告' : '注意'}</span>
        <span class="alert-message">${alert.message}</span>
      </div>
    `).join("") : '<div class="alert-item"><span class="alert-message">現在アラートはありません</span></div>';

    container.querySelector("#inventory-alerts").innerHTML = html;
  }

  // イベント・季節要因
  function updateEventFactors(eventData) {
    const today = new Date();
    const futureEvents = eventData
      .filter(e => new Date(e.開始日時) >= today)
      .sort((a, b) => new Date(a.開始日時) - new Date(b.開始日時))
      .slice(0, 5);

    const html = futureEvents.length > 0 ? futureEvents.map(event => {
      const date = new Date(event.開始日時);
      const dateStr = `${date.getMonth() + 1}/${date.getDate()}`;
      return `
        <div class="event-item">
          <span class="event-date">${dateStr}</span>
          <span class="event-name">${event.イベント名 || 'イベント'}</span>
          <span class="event-impact">影響度: ${event.影響度 || '中'}</span>
        </div>
      `;
    }).join("") : '<div class="event-item"><span class="event-name">予定されているイベントはありません</span></div>';

    container.querySelector("#event-factors").innerHTML = html;
  }

  // 店舗選択肢を設定
  function setupStoreOptions() {
    const storeData = tables[1]?.records || []; // 店舗マスタ
    const storeSelect = container.querySelector("#store-select");

    storeData.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement("option");
        option.value = store.店舗ID;
        option.textContent = store.店舗名;
        storeSelect.appendChild(option);
      }
    });
  }

  // イベントリスナー設定
  container.querySelector("#btn-refresh").addEventListener("click", updateDashboard);
  container.querySelector("#store-select").addEventListener("change", updateDashboard);
  container.querySelector("#period-select").addEventListener("change", updateDashboard);
  container.querySelector("#btn-retry").addEventListener("click", updateDashboard);

  // 初期化
  setupStoreOptions();
  updateDashboard();
}

function(container, apiUrl, tables) {
  let currentEditId = null;
  let storesData = [];
  let productsData = [];

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#sales-tbody');
    tbody.innerHTML = rows.map(r => {
      const salesDate = r.売上日 ? new Date(r.売上日).toLocaleDateString('ja-JP') : '';
      const storeName = storesData.find(s => s.店舗ID === r.店舗ID)?.店舗名 || '';
      const productName = productsData.find(p => p.商品ID === r.商品ID)?.商品名 || '';
      const weekdays = ['日', '月', '火', '水', '木', '金', '土'];
      const weekday = weekdays[r.曜日区分 - 1] || '';
      const saleFlag = r.特売フラグ ? '特売' : '';

      return `
        <tr data-id="${r.売上実績ID || r.id}">
          <td>${salesDate}</td>
          <td>${storeName}</td>
          <td>${productName}</td>
          <td>${(r.販売数量 || 0).toLocaleString()}</td>
          <td>¥${(r.単価 || 0).toLocaleString()}</td>
          <td>¥${(r.売上金額 || 0).toLocaleString()}</td>
          <td>${weekday}</td>
          <td>${saleFlag}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${r.売上実績ID || r.id}">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${r.売上実績ID || r.id}">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ドロップダウン初期化
  function initDropdowns() {
    const storeSelect = container.querySelector('#select-store');
    const productSelect = container.querySelector('#select-product');
    const formStoreSelect = container.querySelector('#form-store-id');
    const formProductSelect = container.querySelector('#form-product-id');

    // 店舗ドロップダウン
    storesData.forEach(store => {
      if (store.有効フラグ) {
        const option = `<option value="${store.店舗ID}">${store.店舗名}</option>`;
        storeSelect.innerHTML += option;
        formStoreSelect.innerHTML += option;
      }
    });

    // 商品ドロップダウン
    productsData.forEach(product => {
      if (product.有効フラグ) {
        const option = `<option value="${product.商品ID}">${product.商品名}</option>`;
        productSelect.innerHTML += option;
        formProductSelect.innerHTML += option;
      }
    });
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ取得
      const stores = await window.aivicApi.list(1);
      if (stores) storesData = stores;

      // 商品データ取得
      const products = await window.aivicApi.list(2);
      if (products) productsData = products;

      // 売上実績データ取得
      const salesData = await window.aivicApi.list(3);
      if (salesData) {
        renderRows(salesData);
      } else {
        renderRows(tables[3]?.records || []);
      }

      initDropdowns();
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
      renderRows(tables[3]?.records || []);
    }
  }

  // 検索・絞り込み
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const storeId = container.querySelector('#select-store').value;
    const productId = container.querySelector('#select-product').value;
    const dateStart = container.querySelector('#input-date-start').value;
    const dateEnd = container.querySelector('#input-date-end').value;

    try {
      const rows = await window.aivicApi.list(3);
      if (!rows) return;

      const filtered = rows.filter(r => {
        if (storeId && r.店舗ID !== storeId) return false;
        if (productId && r.商品ID !== productId) return false;
        if (dateStart && new Date(r.売上日) < new Date(dateStart)) return false;
        if (dateEnd && new Date(r.売上日) > new Date(dateEnd)) return false;
        return true;
      });

      renderRows(filtered);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // 新規登録ボタン
  container.querySelector('#btn-new').addEventListener('click', () => {
    currentEditId = null;
    container.querySelector('#modal-title').textContent = '売上実績登録';
    container.querySelector('#form-store-id').value = '';
    container.querySelector('#form-product-id').value = '';
    container.querySelector('#form-sales-date').value = '';
    container.querySelector('#form-quantity').value = '';
    container.querySelector('#form-unit-price').value = '';
    container.querySelector('#form-sales-amount').value = '';
    container.querySelector('#form-weather').value = '';
    container.querySelector('#form-temperature').value = '';
    container.querySelector('#form-sale-flag').checked = false;
    container.querySelector('#form-discount-rate').value = '';
    container.querySelector('#modal-form').classList.remove('hidden');
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const storeId = container.querySelector('#form-store-id').value;
    const productId = container.querySelector('#form-product-id').value;
    const salesDate = container.querySelector('#form-sales-date').value;
    const quantity = parseInt(container.querySelector('#form-quantity').value);
    const unitPrice = parseInt(container.querySelector('#form-unit-price').value);
    const salesAmount = parseInt(container.querySelector('#form-sales-amount').value);
    const weather = container.querySelector('#form-weather').value;
    const temperature = container.querySelector('#form-temperature').value;
    const saleFlag = container.querySelector('#form-sale-flag').checked;
    const discountRate = container.querySelector('#form-discount-rate').value;

    // バリデーション
    if (!storeId || !productId || !salesDate || quantity < 0 || unitPrice < 0 || salesAmount < 0) {
      alert('必須項目を正しく入力してください。');
      return;
    }

    // 未来日付チェック
    if (new Date(salesDate) > new Date()) {
      alert('売上日は現在日付以前の日付を入力してください');
      return;
    }

    const salesData = {
      店舗ID: storeId,
      商品ID: productId,
      売上日: salesDate,
      販売数量: quantity,
      単価: unitPrice,
      売上金額: salesAmount,
      曜日区分: new Date(salesDate).getDay() + 1,
      祝日フラグ: false,
      天候区分: weather,
      気温: temperature ? parseInt(temperature) : null,
      特売フラグ: saleFlag,
      割引率: discountRate ? parseInt(discountRate) : 0,
      在庫切れフラグ: false,
      データ取込日時: new Date().toISOString(),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user'
    };

    try {
      let result;
      if (currentEditId) {
        result = await window.aivicApi.update(3, currentEditId, salesData);
      } else {
        result = await window.aivicApi.save(3, salesData);
      }

      if (result) {
        container.querySelector('#modal-form').classList.add('hidden');
        loadInitialData();
        alert(currentEditId ? '更新が完了しました' : '登録が完了しました');
      }
    } catch (error) {
      console.error('保存エラー:', error);
      alert('保存に失敗しました');
    }
  });

  // モーダル閉じる
  container.querySelector('#btn-modal-close').addEventListener('click', () => {
    container.querySelector('#modal-form').classList.add('hidden');
  });

  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('#modal-form').classList.add('hidden');
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const rows = await window.aivicApi.list(3);
      if (!rows || rows.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const headers = ['売上日', '店舗名', '商品名', '販売数量', '単価', '売上金額', '天候区分', '気温', '特売フラグ'];
      let csv = '\uFEFF' + headers.join(',') + '\n';

      rows.forEach(r => {
        const storeName = storesData.find(s => s.店舗ID === r.店舗ID)?.店舗名 || '';
        const productName = productsData.find(p => p.商品ID === r.商品ID)?.商品名 || '';
        const salesDate = r.売上日 ? new Date(r.売上日).toLocaleDateString('ja-JP') : '';
        const saleFlag = r.特売フラグ ? '特売' : '';

        const row = [
          salesDate,
          storeName,
          productName,
          r.販売数量 || 0,
          r.単価 || 0,
          r.売上金額 || 0,
          r.天候区分 || '',
          r.気温 || '',
          saleFlag
        ];
        csv += row.join(',') + '\n';
      });

      const blob = new Blob([csv], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `売上実績_${new Date().toISOString().split('T')[0]}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error('エクスポートエラー:', error);
      alert('エクスポートに失敗しました');
    }
  });

  // インポート機能
  container.querySelector('#btn-import').addEventListener('click', () => {
    container.querySelector('#modal-import').classList.remove('hidden');
  });

  container.querySelector('#btn-import-close').addEventListener('click', () => {
    container.querySelector('#modal-import').classList.add('hidden');
  });

  // テンプレートCSVダウンロード
  container.querySelector('#btn-template').addEventListener('click', () => {
    const headers = ['店舗ID', '商品ID', '売上日', '販売数量', '単価', '売上金額', '天候区分', '気温', '特売フラグ', '割引率'];
    const csv = '\uFEFF' + headers.join(',') + '\n';
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = '売上実績テンプレート.csv';
    a.click();
    URL.revokeObjectURL(url);
  });

  // ドラッグ&ドロップ
  const dropZone = container.querySelector('#drop-zone');
  const fileInput = container.querySelector('#file-input');

  dropZone.addEventListener('click', () => fileInput.click());

  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.classList.add('dragover');
  });

  dropZone.addEventListener('dragleave', () => {
    dropZone.classList.remove('dragover');
  });

  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.classList.remove('dragover');
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFileSelect(files[0]);
    }
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFileSelect(e.target.files[0]);
    }
  });

  function handleFileSelect(file) {
    if (!file.name.endsWith('.csv')) {
      alert('CSVファイルを選択してください');
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const csv = e.target.result;
      const lines = csv.split('\n').filter(line => line.trim());

      if (lines.length === 0) {
        alert('インポート対象のデータが存在しません');
        return;
      }

      const headers = lines[0].split(',');
      const previewSection = container.querySelector('#preview-section');
      const previewThead = container.querySelector('#preview-thead');
      const previewTbody = container.querySelector('#preview-tbody');

      previewThead.innerHTML = '<tr>' + headers.map(h => `<th>${h}</th>`).join('') + '</tr>';

      const previewRows = lines.slice(1, 6); // 最初の5行をプレビュー
      previewTbody.innerHTML = previewRows.map(line => {
        const cells = line.split(',');
        return '<tr>' + cells.map(cell => `<td>${cell}</td>`).join('') + '</tr>';
      }).join('');

      previewSection.classList.remove('hidden');
    };
    reader.readAsText(file);
  }

  // 一括インポート実行
  container.querySelector('#btn-bulk-import').addEventListener('click', async () => {
    const file = fileInput.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      const csv = e.target.result;
      const lines = csv.split('\n').filter(line => line.trim());
      const headers = lines[0].split(',');

      let imported = 0;
      let failed = 0;

      for (let i = 1; i < lines.length; i++) {
        const cells = lines[i].split(',');
        const rowData = {
          店舗ID: cells[0],
          商品ID: cells[1],
          売上日: cells[2],
          販売数量: parseInt(cells[3]) || 0,
          単価: parseInt(cells[4]) || 0,
          売上金額: parseInt(cells[5]) || 0,
          天候区分: cells[6] || '',
          気温: cells[7] ? parseInt(cells[7]) : null,
          特売フラグ: cells[8] === '特売' || cells[8] === 'true',
          割引率: parseInt(cells[9]) || 0,
          曜日区分: new Date(cells[2]).getDay() + 1,
          祝日フラグ: false,
          在庫切れフラグ: false,
          データ取込日時: new Date().toISOString(),
