          更新日時: new Date().toISOString(),
          作成者ID: 'current-user'
        };

        try {
          const result = await window.aivicApi.save(3, rowData);
          if (result) {
            imported++;
          } else {
            failed++;
          }
        } catch (error) {
          failed++;
        }
      }

      alert(`インポート完了: 成功 ${imported}件, 失敗 ${failed}件`);
