  // CSVエクスポート
  async function exportPredictionResults() {
    try {
      const predictions = await window.aivicApi.list(PREDICTION_RESULTS_TABLE);
      if (!predictions || predictions.length === 0) {
        showError('エクスポートするデータがありません');
