      const headers = ['商品名', '商品コード', 'カテゴリ', '予測数量', '予測精度', '推奨発注数量', '予測期間'];
      const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
        predictions.map(row => [
          row.商品名 || '',
          row.商品コード || '',
          row.カテゴリ || '',
          row.予測数量 || 0,
