function(container, apiUrl, tables) {
  let currentProducts = [];
  let stores = [];
  let demandForecasts = [];
  let currentInventory = [];

  // テーブルインデックス
  const STORE_TABLE = 1; // 店舗マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  // 商品テーブル再描画関数
  function renderProducts(products) {
    const tbody = container.querySelector("#product-tbody");

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">該当する商品が見つかりませんでした</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => {
      const forecast = demandForecasts.find(f => f.商品ID === product.id) || {};
      const inventory = Math.floor(Math.random() * 100) + 10; // 模擬在庫データ
      const predictedDemand = forecast.予測数量 || Math.floor(Math.random() * 50) + 10;
      const recommendedOrder = Math.max(0, predictedDemand - inventory);

      return `
        <tr data-id="${product.id}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${getCategoryName(product.商品カテゴリID)}</td>
          <td>${inventory}</td>
          <td>${predictedDemand}</td>
          <td>${recommendedOrder}</td>
          <td>
            <input type="number" class="input order-quantity-input" data-product-id="${product.id}" 
                   value="${recommendedOrder}" min="0" style="width: 80px;">
            <div class="quantity-error hidden" style="color: #ff6a6a; font-size: 12px; margin-top: 2px;"></div>
          </td>
          <td>
            <input type="text" class="input order-reason-input" data-product-id="${product.id}" 
                   placeholder="発注理由" style="width: 120px;">
          </td>
          <td>
            <button class="action-btn order-btn" data-product-id="${product.id}">発注</button>
            <button class="action-btn secondary adjust-btn" data-product-id="${product.id}">調整</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // カテゴリ名取得
  function getCategoryName(categoryId) {
    const categories = {
      'cat1': '食品',
      'cat2': '日用品', 
      'cat3': '衣料品',
      'cat4': '家電'
    };
    return categories[categoryId] || '未分類';
  }

  // 需要予測結果表示
  function renderDemandForecast(storeId) {
    const forecastArea = container.querySelector("#demand-forecast-area");

    if (!storeId) {
      forecastArea.innerHTML = '<p style="color: var(--text-muted);">店舗を選択すると需要予測結果が表示されます</p>';
      return;
    }

    const storeForecast = demandForecasts.filter(f => f.店舗ID === storeId);
    const totalPredicted = storeForecast.reduce((sum, f) => sum + (f.予測数量 || 0), 0);
    const avgAccuracy = storeForecast.length > 0 ? 
      Math.round(storeForecast.reduce((sum, f) => sum + (f.予測精度 || 85), 0) / storeForecast.length) : 85;

    forecastArea.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 15px;">
        <div style="text-align: center;">
          <div style="color: var(--text); font-size: 24px; font-weight: bold;">${totalPredicted}</div>
          <div style="color: var(--text-muted); font-size: 12px;">総予測需要量</div>
        </div>
        <div style="text-align: center;">
          <div style="color: var(--text); font-size: 24px; font-weight: bold;">${avgAccuracy}%</div>
          <div style="color: var(--text-muted); font-size: 12px;">平均予測精度</div>
        </div>
        <div style="text-align: center;">
          <div style="color: var(--text); font-size: 24px; font-weight: bold;">${storeForecast.length}</div>
          <div style="color: var(--text-muted); font-size: 12px;">予測対象商品数</div>
        </div>
      </div>
    `;
  }

  // 店舗選択肢を設定
  function loadStores() {
    window.aivicApi.list(STORE_TABLE).then(storeData => {
      if (storeData) {
        stores = storeData;
        const storeSelect = container.querySelector("#store-select");
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join('');
      }
    });
  }

  // 商品データ読み込み
  function loadProducts(storeId = null, categoryFilter = '', searchKeyword = '') {
    window.aivicApi.list(PRODUCT_TABLE).then(productData => {
      if (productData) {
        let filteredProducts = productData.filter(p => p.有効フラグ);

        // カテゴリフィルター
        if (categoryFilter) {
          filteredProducts = filteredProducts.filter(p => getCategoryName(p.商品カテゴリID) === categoryFilter);
        }

        // 検索キーワードフィルター
        if (searchKeyword) {
          const keyword = searchKeyword.toLowerCase();
          filteredProducts = filteredProducts.filter(p => 
            (p.商品名 && p.商品名.toLowerCase().includes(keyword)) ||
            (p.商品コード && p.商品コード.toLowerCase().includes(keyword))
          );
        }

        currentProducts = filteredProducts;
        renderProducts(storeId ? filteredProducts : []);
      }
    });
  }

  // 需要予測データ読み込み
  function loadDemandForecasts() {
    window.aivicApi.list(DEMAND_FORECAST_TABLE).then(forecastData => {
      if (forecastData) {
        demandForecasts = forecastData;
      }
    });
  }

  // バリデーション関数
  function validateDateRange() {
    const startDate = container.querySelector("#date-start").value;
    const endDate = container.querySelector("#date-end").value;
    const errorDiv = container.querySelector("#date-error");

    if (startDate && endDate && startDate > endDate) {
      errorDiv.textContent = "開始日は終了日より前の日付を入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    errorDiv.classList.add("hidden");
    return true;
  }

  function validateOrderQuantity(input) {
    const value = input.value;
    const errorDiv = input.parentElement.querySelector(".quantity-error");

    if (value === '') {
      errorDiv.textContent = "発注量を入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    if (isNaN(value) || value.includes('.')) {
      errorDiv.textContent = "発注量は数値で入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    const numValue = parseInt(value);
    if (numValue < 0) {
      errorDiv.textContent = "発注量は正の数値を入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    if (numValue === 0) {
      errorDiv.textContent = "発注量は1以上を入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    if (numValue > 999999999) {
      errorDiv.textContent = "発注量が上限を超えています";
      errorDiv.classList.remove("hidden");
      return false;
    }

    errorDiv.classList.add("hidden");
    return true;
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(ORDER_TABLE).then(orderData => {
      if (!orderData) return;

      const headers = ['発注ID', '店舗名', '商品名', '発注日', '発注数量', '発注金額', '発注ステータス', '発注理由'];
      const csvContent = '\uFEFF' + headers.join(',') + '\n' +
        orderData.map(order => {
          const store = stores.find(s => s.id === order.店舗ID);
          const product = currentProducts.find(p => p.id === order.商品ID);
          return [
            order.id || '',
            store ? store.店舗名 : '',
            product ? product.商品名 : '',
            order.発注日 || '',
            order.発注数量 || '',
            order.発注金額 || '',
            order.発注ステータス || '',
            (order.発注理由 || '').replace(/,/g, '，')
          ].map(field => `"${field}"`).join(',');
        }).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注管理_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 発注処理
  function processOrder(productId, quantity, reason) {
    const storeId = container.querySelector("#store-select").value;
    const product = currentProducts.find(p => p.id === productId);

    if (!storeId) {
      alert("店舗を選択してください");
      return;
    }

    const orderData = {
      店舗ID: storeId,
      商品ID: productId,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
      発注数量: parseInt(quantity),
      発注単価: product ? product.単価 : 100,
      発注金額: parseInt(quantity) * (product ? product.単価 : 100),
      発注方法: reason ? 'AI推奨修正' : 'AI推奨採用',
      発注ステータス: '発注済',
      発注理由: reason || 'AI需要予測による推奨発注',
      自動発注フラグ: false,
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    window.aivicApi.save(ORDER_TABLE, orderData).then(result => {
      if (result) {
        alert("発注が完了しました");
        // 発注量入力欄をリセット
        const quantityInput = container.querySelector(`input[data-product-id="${productId}"].order-quantity-input`);
        const reasonInput = container.querySelector(`input[data-product-id="${productId}"].order-reason-input`);
        if (quantityInput) quantityInput.value = '';
        if (reasonInput) reasonInput.value = '';
      }
    });
  }

  // 初期データ読み込み
  loadStores();
  loadProducts();
  loadDemandForecasts();

  // イベントリスナー設定

  // 店舗選択変更
  container.querySelector("#store-select").addEventListener("change", (e) => {
    const storeId = e.target.value;
    renderDemandForecast(storeId);

    if (storeId) {
      const categoryFilter = container.querySelector("#category-select").value;
      const searchKeyword = container.querySelector("#product-search").value;
      loadProducts(storeId, categoryFilter, searchKeyword);
    } else {
      renderProducts([]);
    }
  });

  // カテゴリ選択変更
  container.querySelector("#category-select").addEventListener("change", () => {
    const storeId = container.querySelector("#store-select").value;
    const categoryFilter = container.querySelector("#category-select").value;
    const searchKeyword = container.querySelector("#product-search").value;
    loadProducts(storeId, categoryFilter, searchKeyword);
  });

  // 日付範囲バリデーション
  container.querySelector("#date-start").addEventListener("change", validateDateRange);
  container.querySelector("#date-end").addEventListener("change", validateDateRange);

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    if (!validateDateRange()) return;

    const storeId = container.querySelector("#store-select").value;
    const categoryFilter = container.querySelector("#category-select").value;
    const searchKeyword = container.querySelector("#product-search").value;
    loadProducts(storeId, categoryFilter, searchKeyword);
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // 発注量入力バリデーション
  container.addEventListener("input", (e) => {
    if (e.target.classList.contains("order-quantity-input")) {
      validateOrderQuantity(e.target);
    }
  });

  // 発注・調整ボタンのイベントデリゲーション
  container.addEventListener("click", (e) => {
    const orderBtn = e.target.closest(".order-btn");
    const adjustBtn = e.target.closest(".adjust-btn");

    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"].order-quantity-input`);
      const reasonInput = container.querySelector(`input[data-product-id="${productId}"].order-reason-input`);

      if (!validateOrderQuantity(quantityInput)) return;

      const quantity = quantityInput.value;
      const reason = reasonInput.value;

      // 発注確認ダイアログ表示
      const product = currentProducts.find(p => p.id === productId);
      const confirmContent = container.querySelector("#order-confirm-content");
      confirmContent.innerHTML = `
        <p><strong>商品名:</strong> ${product ? product.商品名 : ''}</p>
        <p><strong>発注数量:</strong> ${quantity}</p>
        <p><strong>発注理由:</strong> ${reason || 'AI需要予測による推奨発注'}</p>
      `;

      const dialog = container.querySelector("#order-dialog");
      dialog.classList.remove("hidden");

      // 確定ボタンにproductIdを設定
      container.querySelector("#btn-confirm-order").dataset.productId = productId;
    }

    if (adjustBtn) {
      const productId = adjustBtn.dataset.productId;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"].order-quantity-input`);

      // 推奨発注量を再設定
      const forecast = demandForecasts.find(f => f.商品ID === productId) || {};
      const inventory = Math.floor(Math.random() * 100) + 10;
      const predictedDemand = forecast.予測数量 || Math.floor(Math.random() * 50) + 10;
      const recommendedOrder = Math.max(0, predictedDemand - inventory);

      quantityInput.value = recommendedOrder;
      validateOrderQuantity(quantityInput);
    }
  });

  // ダイアログのキャンセル・確定
  container.querySelector("#btn-cancel-order").addEventListener("click", () => {
    container.querySelector("#order-dialog").classList.add("hidden");
  });

  container.querySelector("#btn-confirm-order").addEventListener("click", (e) => {
    const productId = e.target.dataset.productId;
    const quantityInput = container.querySelector(`input[data-product-id="${productId}"].order-quantity-input`);
    const reasonInput = container.querySelector(`input[data-product-id="${productId}"].order-reason-input`);

    processOrder(productId, quantityInput.value, reasonInput.value);
    container.querySelector("#order-dialog").classList.add("hidden");
  });
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistoryData = [];
  let filteredData = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    const users = await window.aivicApi.list(0); // ログインユーザーテーブル
    const userSelect = container.querySelector('#user-filter');
    if (users) {
      users.forEach(user => {
        const option = document.createElement('option');
        option.value = user.ユーザーID;
        option.textContent = user.ユーザー名 || user.ログインID;
        userSelect.appendChild(option);
      });
    }
  }

  // 操作履歴テーブルの再描画
  function renderHistoryRows(rows) {
    const tbody = container.querySelector('#history-tbody');
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(row => {
      const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';
      const resultClass = row.処理結果 === '成功' ? 'success' : row.処理結果 === '失敗' ? 'error' : '';

      return `
        <tr data-id="${row.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${row.ユーザー名 || ''}</td>
          <td>${row.操作種別 || ''}</td>
          <td>${row.操作画面 || ''}</td>
          <td>${row.IPアドレス || ''}</td>
          <td><span style="color: ${row.処理結果 === '成功' ? '#4ade80' : row.処理結果 === '失敗' ? '#f87171' : 'var(--text)'}">${row.処理結果 || ''}</span></td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    renderPagination(rows.length);
  }

  // ページネーション描画
  function renderPagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pagination = container.querySelector('#pagination');

    if (totalPages <= 1) {
      pagination.innerHTML = '';
      return;
    }

    let paginationHTML = '';

    // 前へボタン
    if (currentPage > 1) {
      paginationHTML += `<button class="action-btn secondary" data-page="${currentPage - 1}">前へ</button>`;
    }

    // ページ番号
    const startPage = Math.max(1, currentPage - 2);
    const endPage = Math.min(totalPages, currentPage + 2);

    for (let i = startPage; i <= endPage; i++) {
      const activeClass = i === currentPage ? 'action-btn' : 'action-btn secondary';
      paginationHTML += `<button class="${activeClass}" data-page="${i}">${i}</button>`;
    }

    // 次へボタン
    if (currentPage < totalPages) {
      paginationHTML += `<button class="action-btn secondary" data-page="${currentPage + 1}">次へ</button>`;
    }

    pagination.innerHTML = paginationHTML;
  }

  // 検索・フィルタリング処理
  async function performSearch() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const userFilter = container.querySelector('#user-filter').value;
    const operationTypeFilter = container.querySelector('#operation-type-filter').value;
    const screenSearch = container.querySelector('#screen-search').value.toLowerCase();
    const ipSearch = container.querySelector('#ip-search').value;
    const resultFilter = container.querySelector('#result-filter').value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を入力してください');
      return;
    }

    // IPアドレスバリデーション
    if (ipSearch && !isValidIP(ipSearch)) {
      alert('正しいIPアドレス形式で入力してください');
      return;
    }

    filteredData = allHistoryData.filter(row => {
      // 日付範囲フィルター
      if (startDate && row.操作日時 && new Date(row.操作日時) < new Date(startDate)) return false;
      if (endDate && row.操作日時 && new Date(row.操作日時) > new Date(endDate)) return false;

      // ユーザーフィルター
      if (userFilter && row.ユーザーID !== userFilter) return false;

      // 操作種別フィルター
      if (operationTypeFilter && row.操作種別 !== operationTypeFilter) return false;

      // 画面名・機能名検索
      if (screenSearch && !row.操作画面?.toLowerCase().includes(screenSearch)) return false;

      // IPアドレス検索
      if (ipSearch && row.IPアドレス !== ipSearch) return false;

      // 操作結果フィルター
      if (resultFilter && row.処理結果 !== resultFilter) return false;

      return true;
    });

    currentPage = 1;
    renderHistoryRows(filteredData);

    if (filteredData.length === 0) {
      const tbody = container.querySelector('#history-tbody');
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
      container.querySelector('#pagination').innerHTML = '';
    }
  }

  // IPアドレス形式チェック
  function isValidIP(ip) {
    // IPv4チェック
    const ipv4Regex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    // IPv6チェック（簡易版）
    const ipv6Regex = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$/;

    return ipv4Regex.test(ip) || ipv6Regex.test(ip);
  }

  // CSV出力
  function exportToCSV() {
    if (filteredData.length === 0) {
      alert('出力可能なデータがありません');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', 'IPアドレス', '処理結果', '操作内容'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...filteredData.map(row => [
        row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '',
        row.ユーザー名 || '',
        row.操作種別 || '',
        row.操作画面 || '',
        row.IPアドレス || '',
        row.処理結果 || '',
        (row.操作内容 || '').replace(/,/g, '，').replace(/\n/g, ' ')
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `操作履歴_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistoryData.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const modal = container.querySelector('#detail-modal');
    const content = container.querySelector('#detail-content');

    content.innerHTML = `
      <div style="display: grid; grid-template-columns: 150px 1fr; gap: 12px; line-height: 1.6;">
        <div><strong>操作日時:</strong></div>
        <div>${history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : ''}</div>

        <div><strong>ユーザー名:</strong></div>
        <div>${history.ユーザー名 || ''}</div>

        <div><strong>操作種別:</strong></div>
        <div>${history.操作種別 || ''}</div>

        <div><strong>操作画面:</strong></div>
        <div>${history.操作画面 || ''}</div>

        <div><strong>操作対象テーブル:</strong></div>
        <div>${history.操作対象テーブル || ''}</div>

        <div><strong>操作対象ID:</strong></div>
        <div>${history.操作対象ID || ''}</div>

        <div><strong>IPアドレス:</strong></div>
        <div>${history.IPアドレス || ''}</div>

        <div><strong>ユーザーエージェント:</strong></div>
        <div style="word-break: break-all;">${history.ユーザーエージェント || ''}</div>

        <div><strong>処理結果:</strong></div>
        <div style="color: ${history.処理結果 === '成功' ? '#4ade80' : history.処理結果 === '失敗' ? '#f87171' : 'var(--text)'}">${history.処理結果 || ''}</div>

        <div><strong>エラーメッセージ:</strong></div>
        <div>${history.エラーメッセージ || ''}</div>

        <div><strong>処理時間:</strong></div>
        <div>${history.処理時間 ? history.処理時間 + 'ms' : ''}</div>

        <div><strong>操作内容:</strong></div>
        <div style="white-space: pre-wrap; background: var(--bg-main); padding: 12px; border-radius: 4px; border: 1px solid var(--border);">${history.操作内容 || ''}</div>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    const historyData = await window.aivicApi.list(13); // システム操作履歴テーブル
    if (historyData) {
      allHistoryData = historyData;
      filteredData = [...allHistoryData];
      renderHistoryRows(filteredData);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#user-filter').value = '';
    container.querySelector('#operation-type-filter').value = '';
    container.querySelector('#screen-search').value = '';
    container.querySelector('#ip-search').value = '';
    container.querySelector('#result-filter').value = '';

    filteredData = [...allHistoryData];
    currentPage = 1;
    renderHistoryRows(filteredData);
  });

  container.querySelector('#btn-csv-export').addEventListener('click', exportToCSV);

  // ページネーションクリック
  container.querySelector('#pagination').addEventListener('click', (e) => {
    const pageBtn = e.target.closest('[data-page]');
    if (pageBtn) {
      const page = parseInt(pageBtn.dataset.page);
      if (page > 0 && page <= Math.ceil(filteredData.length / itemsPerPage)) {
        currentPage = page;
        renderHistoryRows(filteredData);
      }
    }
  });

  // 詳細ボタンクリック
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル閉じる
  container.querySelector('#close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#detail-modal')) {
      container.querySelector('#detail-modal').classList.add('hidden');
    }
  });

  // 初期化
  loadUsers();
  loadInitialData();
}

function(container, apiUrl, tables) {
  // 初期化処理
  const storeSelect = container.querySelector('#store-select');
  const categoryCheckboxes = container.querySelector('#category-checkboxes');
  const progressContainer = container.querySelector('#progress-container');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const progressStatus = container.querySelector('#progress-status');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');
  const successMessage = container.querySelector('#success-message');
  const successText = container.querySelector('#success-text');

  // 今日の日付を設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const oneYearAgo = new Date(today);
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);

  container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
  container.querySelector('#prediction-end-date').value = new Date(tomorrow.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  container.querySelector('#learning-start-date').value = oneYearAgo.toISOString().split('T')[0];
  container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];

  // 店舗データの読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリの読み込み（商品マスタから商品カテゴリIDを抽出）
  async function loadCategories() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      const categoryIds = [...new Set(products.map(p => p.商品カテゴリID))];
      categoryIds.forEach((categoryId, index) => {
        const label = document.createElement('label');
        label.style.display = 'flex';
        label.style.alignItems = 'center';
        label.style.marginBottom = '8px';
        label.style.color = 'var(--text)';

        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.value = categoryId;
        checkbox.style.marginRight = '8px';

        label.appendChild(checkbox);
        label.appendChild(document.createTextNode(`カテゴリ ${index + 1}`));
        categoryCheckboxes.appendChild(label);
      });
    }
  }

  // 季節要因スライダーの値更新
  ['spring', 'summer', 'autumn', 'winter'].forEach(season => {
    const slider = container.querySelector(`#${season}-factor`);
    const valueSpan = container.querySelector(`#${season}-value`);
    slider.addEventListener('input', () => {
      valueSpan.textContent = slider.value;
    });
  });

  // エラー表示関数
  function showError(message) {
    errorText.textContent = message;
    errorMessage.classList.remove('hidden');
    successMessage.classList.add('hidden');
  }

  // 成功表示関数
  function showSuccess(message) {
    successText.textContent = message;
    successMessage.classList.remove('hidden');
    errorMessage.classList.add('hidden');
  }

  // エラー・成功メッセージを隠す
  function hideMessages() {
    errorMessage.classList.add('hidden');
    successMessage.classList.add('hidden');
  }

  // 進捗バー更新
  function updateProgress(percent, status) {
    progressBar.style.width = `${percent}%`;
    progressText.textContent = `${percent}%`;
    progressStatus.textContent = status;
  }

  // バリデーション関数
  function validateForm() {
    hideMessages();

    const startDate = container.querySelector('#prediction-start-date').value;
    const endDate = container.querySelector('#prediction-end-date').value;
    const storeId = storeSelect.value;
    const selectedCategories = Array.from(categoryCheckboxes.querySelectorAll('input[type="checkbox"]:checked'));
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;
    const accuracyThreshold = parseInt(container.querySelector('#accuracy-threshold').value);

    // 予測対象期間チェック
    if (!startDate || !endDate) {
      showError('予測対象期間を設定してください。');
      return false;
    }

    const today = new Date().toISOString().split('T')[0];
    if (startDate <= today) {
      showError('予測対象期間に過去の日付は選択できません。');
      return false;
    }

    if (startDate >= endDate) {
      showError('予測対象期間の終了日は開始日より後の日付を選択してください。');
      return false;
    }

    // 店舗選択チェック
    if (!storeId) {
      showError('店舗を選択してください。');
      return false;
    }

    // 商品カテゴリ選択チェック
    if (selectedCategories.length === 0) {
      showError('商品カテゴリを選択してください。');
      return false;
    }

    // 予測モデル選択チェック
    if (!selectedModel) {
      showError('予測モデルを選択してください。');
      return false;
    }

    // 学習データ期間チェック
    if (!learningStart || !learningEnd) {
      showError('学習データ期間を設定してください。');
      return false;
    }

    // 予測精度閾値チェック
    if (isNaN(accuracyThreshold) || accuracyThreshold < 0 || accuracyThreshold > 100) {
