function(container, apiUrl, tables) {
  let storeData = [];
  let productData = [];
  let forecastData = [];
  let calculationResults = [];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-display');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      storeData = stores.filter(s => s.有効フラグ);
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      storeData.forEach(store => {
        storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
      });
    }
  }

  // 商品データ読み込み
  async function loadProducts() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      productData = products.filter(p => p.有効フラグ);
    }
  }

  // 商品検索・絞り込み
  function filterProducts() {
    const searchTerm = container.querySelector('#product-search').value.toLowerCase();
    const categoryFilter = container.querySelector('#category-select').value;

    let filtered = productData;

    if (searchTerm) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchTerm) ||
        (p.商品コード || '').toLowerCase().includes(searchTerm)
      );
    }

    if (categoryFilter) {
      filtered = filtered.filter(p => p.商品カテゴリID === categoryFilter);
    }

    return filtered;
  }

  // 需要予測結果表示
  function displayForecast(storeId, startDate, endDate) {
    const forecastDiv = container.querySelector('#forecast-display');

    if (!storeId || !startDate || !endDate) {
      forecastDiv.innerHTML = '<p class="muted">店舗と期間を選択して「予測更新」ボタンをクリックしてください</p>';
      return;
    }

    // 簡易的な予測表示（実際のAI予測データを使用する場合は需要予測結果テーブルから取得）
    const store = storeData.find(s => s.id === storeId);
    const storeName = store ? store.店舗名 : '選択された店舗';

    forecastDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1rem;">
        <div>
          <strong>対象店舗:</strong> ${storeName}<br>
          <strong>予測期間:</strong> ${startDate} ～ ${endDate}
        </div>
        <div>
          <strong>予測精度:</strong> 85%<br>
          <strong>予測モデル:</strong> v2.1
        </div>
      </div>
      <div style="margin-top: 1rem; padding: 1rem; background: var(--bg-card); border-radius: 4px;">
        <p style="color: var(--text);">需要予測が更新されました。商品を検索して発注量を計算してください。</p>
      </div>
    `;
  }

  // 発注量計算結果テーブル描画
  function renderCalculationResults(results) {
    const tbody = container.querySelector('#calculation-tbody');

    if (!results || results.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 2rem;">
            商品を検索して発注量を計算してください
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id}">
        <td>${result.商品名 || ''}</td>
        <td>${result.商品コード || ''}</td>
        <td>${result.予測需要量 || 0}</td>
        <td>
          <input type="number" class="input current-stock-input" 
                 data-product-id="${result.id}" 
                 value="${result.現在在庫 || 0}" 
                 min="0" style="width: 80px;">
        </td>
        <td>${result.AI推奨発注量 || 0}</td>
        <td>
          <input type="number" class="input manual-adjust-input" 
                 data-product-id="${result.id}" 
                 value="${result.手動調整 || 0}" 
                 min="0" style="width: 80px;">
        </td>
        <td><strong>${result.最終発注量 || 0}</strong></td>
        <td>
          <button class="action-btn secondary calculate-single-btn" data-product-id="${result.id}">再計算</button>
        </td>
      </tr>
    `).join('');

    // 在庫数・手動調整の変更イベント
    tbody.querySelectorAll('.current-stock-input, .manual-adjust-input').forEach(input => {
      input.addEventListener('change', (e) => {
        const productId = e.target.dataset.productId;
        const result = calculationResults.find(r => r.id === productId);
        if (result) {
          if (e.target.classList.contains('current-stock-input')) {
            const value = parseInt(e.target.value) || 0;
            if (value < 0) {
              showError('現在在庫数は0以上の値を入力してください');
              e.target.value = 0;
              return;
            }
            result.現在在庫 = value;
          } else {
            const value = parseInt(e.target.value) || 0;
            if (value < 0) {
              showError('手動調整値は0以上の値を入力してください');
              e.target.value = 0;
              return;
            }
            result.手動調整 = value;
          }
          calculateSingleProduct(result);
          renderCalculationResults(calculationResults);
        }
      });
    });
  }

  // 単一商品の発注量計算
  function calculateSingleProduct(result) {
    const currentStock = parseInt(container.querySelector('#current-stock').value) || result.現在在庫 || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 7;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;

    // 基本予測需要量（サンプル計算）
    const baseDemand = Math.floor(Math.random() * 100) + 50;

    // 天候・イベント影響調整
    const adjustedDemand = Math.floor(baseDemand * (weatherImpact / 100));

    // 季節補正
    const seasonalDemand = Math.floor(adjustedDemand * seasonalFactor);

    // リードタイム期間の需要
    const leadTimeDemand = Math.floor(seasonalDemand * (leadTime / 7));

    // AI推奨発注量 = 予測需要 + 安全在庫 - 現在在庫 + リードタイム需要
    const aiRecommended = Math.max(0, seasonalDemand + safetyStock - currentStock + leadTimeDemand);

    // 最終発注量 = AI推奨 + 手動調整
    const finalOrder = aiRecommended + (result.手動調整 || 0);

    result.予測需要量 = seasonalDemand;
    result.現在在庫 = currentStock;
    result.AI推奨発注量 = aiRecommended;
    result.最終発注量 = finalOrder;
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#period-start').value;
    const endDate = container.querySelector('#period-end').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を選択してください');
      return false;
    }

    // 未来日のみの期間チェック
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (new Date(startDate) > today && new Date(endDate) > today) {
      showError('対象期間に過去または現在の日付を含めてください');
      return false;
    }

    const leadTime = parseInt(container.querySelector('#lead-time').value);
    if (leadTime && (leadTime < 1 || leadTime > 365)) {
      showError('リードタイムは1日から365日の範囲で入力してください');
      return false;
    }

    const weatherImpact = parseInt(container.querySelector('#weather-impact').value);
    if (weatherImpact && (weatherImpact < 0 || weatherImpact > 100)) {
      showError('影響度調整は0%から100%の範囲で入力してください');
      return false;
    }

    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value);
    if (seasonalFactor && seasonalFactor < 0) {
      showError('季節補正係数は0以上の値を入力してください');
      return false;
    }

    return true;
  }

  // 初期データ読み込み
  loadStores();
  loadProducts();

  // 今日の日付を初期値として設定
  const today = new Date();
  const todayStr = today.toISOString().split('T')[0];
  const weekLater = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  const weekLaterStr = weekLater.toISOString().split('T')[0];

  container.querySelector('#period-start').value = todayStr;
  container.querySelector('#period-end').value = weekLaterStr;
  container.querySelector('#lead-time').value = '7';
  container.querySelector('#weather-impact').value = '100';
  container.querySelector('#seasonal-factor').value = '1.0';

  // イベントリスナー
  container.querySelector('#btn-search-product').addEventListener('click', () => {
    const filtered = filterProducts();
    calculationResults = filtered.slice(0, 20).map(product => ({
      id: product.id,
      商品名: product.商品名,
      商品コード: product.商品コード,
      予測需要量: 0,
      現在在庫: 0,
      AI推奨発注量: 0,
      手動調整: 0,
      最終発注量: 0
    }));
    renderCalculationResults(calculationResults);
  });

  container.querySelector('#btn-filter').addEventListener('click', () => {
    container.querySelector('#btn-search-product').click();
  });

  container.querySelector('#btn-update-forecast').addEventListener('click', () => {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#period-start').value;
    const endDate = container.querySelector('#period-end').value;

    if (!validateInputs()) return;

    displayForecast(storeId, startDate, endDate);
  });

  container.querySelector('#btn-calculate').addEventListener('click', () => {
    if (!validateInputs()) return;

    if (calculationResults.length === 0) {
      showError('計算対象の商品を検索してください');
      return;
    }

    calculationResults.forEach(result => calculateSingleProduct(result));
    renderCalculationResults(calculationResults);
  });

  container.querySelector('#btn-calculate-all').addEventListener('click', () => {
    if (!validateInputs()) return;

    const filtered = filterProducts();
    calculationResults = filtered.map(product => ({
      id: product.id,
      商品名: product.商品名,
      商品コード: product.商品コード,
      予測需要量: 0,
      現在在庫: 0,
      AI推奨発注量: 0,
      手動調整: 0,
      最終発注量: 0
    }));

    calculationResults.forEach(result => calculateSingleProduct(result));
    renderCalculationResults(calculationResults);
  });

  // 単一商品再計算
  container.addEventListener('click', (e) => {
    const btn = e.target.closest('.calculate-single-btn');
    if (btn) {
      const productId = btn.dataset.productId;
      const result = calculationResults.find(r => r.id === productId);
      if (result) {
        calculateSingleProduct(result);
        renderCalculationResults(calculationResults);
      }
    }
  });

  // 初期表示
  renderCalculationResults([]);
}

function(container, apiUrl, tables) {
  let stores = [];
  let products = [];
  let categories = [];
  let orderItems = [];
  let currentPredictions = {};

  // 初期データの設定
  if (tables[1] && tables[1].records) stores = tables[1].records;
  if (tables[2] && tables[2].records) products = tables[2].records;

  // カテゴリ一覧を商品から抽出
  const categoryIds = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
  categories = categoryIds.map(id => ({ id, name: `カテゴリ${id.slice(-4)}` }));

  // 今日の日付を発注日にセット
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 店舗選択肢を設定
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
      stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join('');
  }

  // カテゴリ選択肢を設定
  function renderCategoryOptions() {
    const categorySelect = container.querySelector('#category-select');
    categorySelect.innerHTML = '<option value="">全カテゴリ</option>' +
      categories.map(cat => `<option value="${cat.id}">${cat.name}</option>`).join('');
  }

  // 商品一覧を描画
  function renderProductList(filteredProducts = products) {
    const tbody = container.querySelector('#product-list');
    tbody.innerHTML = filteredProducts.map(product => {
      const prediction = currentPredictions[product.商品ID] || 0;
      return `
        <tr data-id="${product.商品ID}">
          <td style="color: var(--text);">${product.商品コード || ''}</td>
          <td style="color: var(--text);">${product.商品名 || ''}</td>
          <td style="color: var(--text);">${product.単価 || 0}円</td>
          <td style="color: var(--text);">100</td>
          <td style="color: var(--text);"><span class="ai-prediction" data-product-id="${product.商品ID}">${prediction}</span></td>
          <td>
            <input type="number" class="input manual-quantity" data-product-id="${product.商品ID}" 
                   style="width: 80px;" min="0" value="${prediction}">
          </td>
          <td>
            <button class="action-btn secondary add-to-order" data-product-id="${product.商品ID}">追加</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 発注商品一覧を描画
  function renderOrderItems() {
    const tbody = container.querySelector('#order-items-list');
    tbody.innerHTML = orderItems.map(item => `
      <tr data-id="${item.商品ID}">
        <td style="color: var(--text);">${item.商品コード}</td>
        <td style="color: var(--text);">${item.商品名}</td>
        <td style="color: var(--text);">${item.発注数量}</td>
        <td style="color: var(--text);">${item.単価}円</td>
        <td style="color: var(--text);">${item.発注数量 * item.単価}円</td>
        <td>
          <button class="action-btn secondary remove-from-order" data-product-id="${item.商品ID}">削除</button>
        </td>
      </tr>
    `).join('');

    // 発注総額を更新
    const totalAmount = orderItems.reduce((sum, item) => sum + (item.発注数量 * item.単価), 0);
    container.querySelector('#total-amount').textContent = totalAmount.toLocaleString();
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // AI予測数量を取得（模擬）
  async function fetchAIPredictions(storeId) {
    // 実際のAI予測APIを呼ぶ代わりに、模擬データを生成
    currentPredictions = {};
    products.forEach(product => {
      currentPredictions[product.商品ID] = Math.floor(Math.random() * 50) + 10;
    });

    // 画面上のAI予測数量を更新
    container.querySelectorAll('.ai-prediction').forEach(span => {
      const productId = span.dataset.productId;
      const prediction = currentPredictions[productId] || 0;
      span.textContent = prediction;

      // 手動調整数量も更新
      const manualInput = container.querySelector(`.manual-quantity[data-product-id="${productId}"]`);
      if (manualInput && !manualInput.value) {
        manualInput.value = prediction;
      }
    });
  }

  // 商品検索
  function searchProducts() {
    const searchTerm = container.querySelector('#product-search').value.toLowerCase();
    const selectedCategory = container.querySelector('#category-select').value;

    let filtered = products.filter(product => {
      const matchesSearch = !searchTerm || 
        (product.商品名 && product.商品名.toLowerCase().includes(searchTerm)) ||
        (product.商品コード && product.商品コード.toLowerCase().includes(searchTerm));

      const matchesCategory = !selectedCategory || product.商品カテゴリID === selectedCategory;

      return matchesSearch && matchesCategory && product.有効フラグ;
    });

    renderProductList(filtered);
  }

  // 初期描画
  renderStoreOptions();
  renderCategoryOptions();
  renderProductList();
  renderOrderItems();

  // イベントリスナー

  // 店舗選択時にAI予測を取得
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    if (e.target.value) {
      await fetchAIPredictions(e.target.value);
    }
  });

  // カテゴリ選択・商品検索
  container.querySelector('#category-select').addEventListener('change', searchProducts);
  container.querySelector('#product-search').addEventListener('input', searchProducts);

  // 手動調整数量の入力検証
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('manual-quantity')) {
      const value = parseInt(e.target.value);
      if (value < 0) {
        showError('手動調整数量は0以上の値を入力してください');
        e.target.style.borderColor = '#ff6b6b';
      } else {
        e.target.style.borderColor = '';
      }
    }
  });

  // 発注日・納期の検証
  container.querySelector('#order-date').addEventListener('change', (e) => {
    const orderDate = new Date(e.target.value);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (orderDate < today) {
      showError('発注日に過去の日付は設定できません');
      e.target.value = today.toISOString().split('T')[0];
    }
  });

  container.querySelector('#delivery-date').addEventListener('change', (e) => {
    const deliveryDate = new Date(e.target.value);
    const orderDate = new Date(container.querySelector('#order-date').value);

    if (deliveryDate < orderDate) {
      showError('納期は発注日以降の日付を設定してください');
      e.target.value = '';
    }
  });

  // 予測根拠表示
  container.querySelector('#btn-prediction-basis').addEventListener('click', () => {
    const area = container.querySelector('#prediction-basis-area');
    const content = container.querySelector('#prediction-basis-content');

    if (area.classList.contains('hidden')) {
      content.innerHTML = `
        <div style="margin-bottom: 12px;">
          <strong>予測要因分析:</strong><br>
          • 過去3ヶ月の売上トレンド: +15%<br>
          • 季節性要因: 春季需要増加 (+8%)<br>
          • 天候要因: 晴天予報による外出増加 (+5%)<br>
          • イベント要因: 近隣イベント開催 (+12%)
        </div>
        <div>
          <strong>予測精度:</strong> 87%<br>
          <strong>信頼区間:</strong> ±10%
        </div>
      `;
      area.classList.remove('hidden');
    } else {
      area.classList.add('hidden');
    }
  });

  // 在庫状況確認
  container.querySelector('#btn-stock-check').addEventListener('click', () => {
    alert('在庫状況: 全商品の在庫データを最新に更新しました。\n在庫不足商品: 3件\n適正在庫商品: 47件');
  });

  // 過去実績参照
  container.querySelector('#btn-past-records').addEventListener('click', () => {
    alert('過去実績データ:\n• 先月売上: 前年同月比 +12%\n• 平均発注サイクル: 3.2日\n• 在庫回転率: 8.5回/月');
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 商品を発注リストに追加
    const addBtn = e.target.closest('.add-to-order');
    if (addBtn) {
      const productId = addBtn.dataset.productId;
      const product = products.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`.manual-quantity[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;

      if (quantity <= 0) {
        showError('発注数量を正しく入力してください');
        return;
      }

      // 既存アイテムをチェック
      const existingIndex = orderItems.findIndex(item => item.商品ID === productId);
      if (existingIndex >= 0) {
        orderItems[existingIndex].発注数量 = quantity;
      } else {
        orderItems.push({
          商品ID: productId,
          商品コード: product.商品コード,
          商品名: product.商品名,
          発注数量: quantity,
          単価: product.単価 || 0
        });
      }

      renderOrderItems();
    }

    // 発注リストから商品を削除
    const removeBtn = e.target.closest('.remove-from-order');
    if (removeBtn) {
      const productId = removeBtn.dataset.productId;
      orderItems = orderItems.filter(item => item.商品ID !== productId);
      renderOrderItems();
    }
  });

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', async () => {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    // バリデーション
    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を入力してください');
      return;
    }

    if (!deliveryDate) {
      showError('納期を指定してください');
      return;
    }

    if (orderItems.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    // 発注データを保存
    try {
      for (const item of orderItems) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.商品ID,
          発注日: orderDate + 'T00:00:00Z',
          納期予定日: deliveryDate + 'T00:00:00Z',
          発注数量: item.発注数量,
          発注単価: item.単価,
          発注金額: item.発注数量 * item.単価,
          発注方法: '手動発注',
          発注ステータス: '発注済',
          仕入先ID: '00000000-0000-0000-0000-000000000001',
          自動発注フラグ: false,
          作成者ID: '00000000-0000-0000-0000-000000000001',
          更新者ID: '00000000-0000-0000-0000-000000000001'
        };

        await window.aivicApi.save(7, orderData); // 発注データテーブル
      }

      alert('発注書を作成しました');
      window.showScreen('scr-1778591852463'); // 発注管理画面に遷移

    } catch (error) {
      showError('発注書の作成に失敗しました');
    }
  });
}

function(container, apiUrl, tables) {
  let currentStoreId = '';
  let selectedOrders = new Set();
  let allOrders = [];

  // テーブル再描画関数
  function renderOrders(orders) {
    const tbody = container.querySelector('#order-tbody');
    const noDataMessage = container.querySelector('#no-data-message');
    const sendBtn = container.querySelector('#btn-send');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.classList.remove('hidden');
      sendBtn.disabled = true;
      return;
    }

    noDataMessage.classList.add('hidden');

    tbody.innerHTML = orders.map(order => {
      const statusClass = order.発注ステータス === '送信済み' ? 'status-sent' : 
                         order.発注ステータス === 'エラー' ? 'status-error' : 'status-pending';
      const isDisabled = order.発注ステータス === '送信済み' ? 'disabled' : '';
      const isChecked = selectedOrders.has(order.id) ? 'checked' : '';

      return `
        <tr data-id="${order.id}">
          <td>
            <input type="checkbox" class="individual-checkbox" data-id="${order.id}" ${isChecked} ${isDisabled}>
          </td>
          <td>${order.商品コード || ''}</td>
          <td>${order.商品名 || ''}</td>
          <td class="text-right">${order.予測数量 ? order.予測数量.toLocaleString() : ''}</td>
          <td class="text-right">${order.発注数量 ? order.発注数量.toLocaleString() : ''}</td>
          <td>${order.仕入先名 || ''}</td>
          <td class="text-right">¥${order.発注金額 ? order.発注金額.toLocaleString() : '0'}</td>
          <td><span class="status-badge ${statusClass}">${order.発注ステータス || '送信待ち'}</span></td>
        </tr>
      `;
    }).join('');

    updateSendButton();
  }

  // 店舗選択ドロップダウンを初期化
  async function initStoreSelect() {
    const storeSelect = container.querySelector('#store-select');
    const stores = await window.aivicApi.list(1); // 店舗マスタ

    if (stores) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.filter(store => store.有効フラグ).map(store => 
          `<option value="${store.id}">${store.店舗名}</option>`
        ).join('');
    }
  }

  // 発注データを店舗で絞り込み
  async function loadOrdersByStore(storeId) {
    if (!storeId) {
      renderOrders([]);
      return;
    }

    const orders = await window.aivicApi.list(7); // 発注データ
    if (orders) {
      const filteredOrders = orders.filter(order => order.店舗ID === storeId);

      // 商品情報と仕入先情報を結合
      const products = await window.aivicApi.list(2); // 商品マスタ
      const predictions = await window.aivicApi.list(6); // 需要予測結果

      const enrichedOrders = filteredOrders.map(order => {
        const product = products?.find(p => p.id === order.商品ID);
        const prediction = predictions?.find(p => p.id === order.需要予測結果ID);

        return {
          ...order,
          商品コード: product?.商品コード || '',
          商品名: product?.商品名|| '',
          仕入先名: '仕入先A', // 実際は仕入先マスタから取得
          予測数量: prediction?.予測数量 || 0
        };
      });

      allOrders = enrichedOrders;
      renderOrders(enrichedOrders);
    }
  }

  // 送信ボタンの状態更新
  function updateSendButton() {
    const sendBtn = container.querySelector('#btn-send');
    const hasSelection = selectedOrders.size > 0;
    sendBtn.disabled = !hasSelection;
    sendBtn.textContent = hasSelection ? `選択した${selectedOrders.size}件の発注を送信` : '選択した発注を送信';
  }

  // 全選択チェックボックスの処理
  function handleSelectAll() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const individualCheckboxes = container.querySelectorAll('.individual-checkbox:not([disabled])');

    if (selectAllCheckbox.checked) {
      selectedOrders.clear();
      individualCheckboxes.forEach(cb => {
        selectedOrders.add(cb.dataset.id);
        cb.checked = true;
      });
    } else {
      selectedOrders.clear();
      individualCheckboxes.forEach(cb => {
        cb.checked = false;
      });
    }

    updateSendButton();
  }

  // 個別選択チェックボックスの処理
  function handleIndividualSelect(checkbox) {
    const orderId = checkbox.dataset.id;

    if (checkbox.checked) {
      selectedOrders.add(orderId);
    } else {
      selectedOrders.delete(orderId);
    }

    // 全選択チェックボックスの状態更新
    const selectAllCheckbox = container.querySelector('#select-all');
    const totalCheckboxes = container.querySelectorAll('.individual-checkbox:not([disabled])').length;
    selectAllCheckbox.checked = selectedOrders.size === totalCheckboxes && totalCheckboxes > 0;

    updateSendButton();
  }

  // 発注送信処理
  async function sendOrders() {
    if (selectedOrders.size === 0) {
      showMessage('発注対象が選択されていません', 'error');
      return;
    }

    // 確認ダイアログ表示
    const confirmDialog = container.querySelector('#confirm-dialog');
    const confirmMessage = container.querySelector('#confirm-message');
    confirmMessage.textContent = `選択した${selectedOrders.size}件の発注データを送信しますか？`;
    confirmDialog.classList.remove('hidden');
  }

  // 実際の送信処理
  async function executeSend() {
    const confirmDialog = container.querySelector('#confirm-dialog');
    confirmDialog.classList.add('hidden');

    let successCount = 0;
    let errorCount = 0;

    try {
      // 選択された発注データを送信済みに更新
      for (const orderId of selectedOrders) {
        const updated = await window.aivicApi.update(7, orderId, {
          発注ステータス: '送信済み',
          更新日時: new Date().toISOString()
        });

        if (updated) {
          successCount++;
        } else {
          errorCount++;
          // 通信エラーの場合はエラーステータスに更新
          await window.aivicApi.update(7, orderId, {
            発注ステータス: 'エラー',
            更新日時: new Date().toISOString()
          });
        }
      }

      if (successCount > 0) {
        showMessage(`${successCount}件の発注データの送信が完了しました`, 'success');
      }
      if (errorCount > 0) {
        showMessage(`${errorCount}件の発注データの送信に失敗しました`, 'error');
      }

      // 選択をクリアして再読み込み
      selectedOrders.clear();
      const selectAllCheckbox = container.querySelector('#select-all');
      selectAllCheckbox.checked = false;

      await loadOrdersByStore(currentStoreId);

    } catch (error) {
      showMessage('通信エラーが発生しました。ネットワーク接続を確認してください。', 'error');
    }
  }

  // メッセージ表示
  function showMessage(text, type) {
    const messageArea = container.querySelector('#message-area');
    messageArea.textContent = text;
    messageArea.className = `message-${type}`;
    messageArea.classList.remove('hidden');

    setTimeout(() => {
      messageArea.classList.add('hidden');
    }, 5000);
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 店舗選択
    const storeSelect = container.querySelector('#store-select');
    storeSelect.addEventListener('change', async (e) => {
      currentStoreId = e.target.value;
      selectedOrders.clear();
      const selectAllCheckbox = container.querySelector('#select-all');
      selectAllCheckbox.checked = false;
      await loadOrdersByStore(currentStoreId);
    });

    // 全選択チェックボックス
    const selectAllCheckbox = container.querySelector('#select-all');
    selectAllCheckbox.addEventListener('change', handleSelectAll);

    // 送信ボタン
    const sendBtn = container.querySelector('#btn-send');
    sendBtn.addEventListener('click', sendOrders);

    // 確認ダイアログ
    const confirmOk = container.querySelector('#confirm-ok');
    const confirmCancel = container.querySelector('#confirm-cancel');
    const confirmDialog = container.querySelector('#confirm-dialog');

    confirmOk.addEventListener('click', executeSend);
    confirmCancel.addEventListener('click', () => {
      confirmDialog.classList.add('hidden');
    });

    // イベントデリゲーション（個別チェックボックス）
    container.addEventListener('change', (e) => {
      if (e.target.classList.contains('individual-checkbox')) {
        handleIndividualSelect(e.target);
      }
    });
  }

  // 初期化
  async function init() {
    await initStoreSelect();
    setupEventListeners();

    // 初期データ表示（店舗未選択時は空）
    renderOrders([]);
  }

  init();
}

function(container, apiUrl, tables) {
  let calculationResults = [];

  // エラー・成功メッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    const successText = container.querySelector('#success-text');
    successText.textContent = message;
    successDiv.classList.remove('hidden');
    setTimeout(() => successDiv.classList.add('hidden'), 3000);
  }

  // 店舗データ読み込み
  async function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeSelect.innerHTML = stores.filter(s => s.有効フラグ).map(store => 
          `<option value="${store.店舗ID}">${store.店舗名}</option>`
        ).join('');
      }
    } catch (error) {
      console.error('店舗データ読み込みエラー:', error);
    }
  }

  // 計算結果テーブル再描画
  function renderResults(results) {
    const tbody = container.querySelector('#results-tbody');
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="12" class="muted" style="text-align: center; padding: 40px;">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id || Math.random()}">
        <td><input type="checkbox" class="result-checkbox" data-id="${result.id || Math.random()}"></td>
        <td>${result.店舗名 || ''}</td>
        <td>${result.商品名 || ''}</td>
        <td>${result.商品コード || ''}</td>
        <td style="text-align: right;">${result.現在在庫数 || 0}</td>
        <td style="text-align: right;">${result.予測需要量 || 0}</td>
        <td style="text-align: right;">${result.安全在庫数 || 0}</td>
        <td style="text-align: right;">${result.発注点 || 0}</td>
        <td style="text-align: right; font-weight: bold;">${result.推奨発注量 || 0}</td>
        <td style="text-align: right;">${(result.発注金額 || 0).toLocaleString()}円</td>
        <td>${result.納期予定日 || ''}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${result.id || Math.random()}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${result.id || Math.random()}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // バリデーション関数
  function validateInputs() {
    const storeSelect = container.querySelector('#store-select');
    const categorySelect = container.querySelector('#category-select');
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');
    const safetyStock = container.querySelector('#safety-stock');
    const leadTime = container.querySelector('#lead-time');
    const orderPoint = container.querySelector('#order-point');

    if (!storeSelect.value && storeSelect.selectedOptions.length === 0) {
      showError('店舗を選択してください');
      return false;
    }

    if (!categorySelect.value) {
      showError('商品カテゴリを選択してください');
      return false;
    }

    if (!periodStart.value || !periodEnd.value) {
      showError('計算対象期間を設定してください');
      return false;
    }

    if (safetyStock.value && parseInt(safetyStock.value) < 0) {
      showError('安全在庫数は0以上の値を入力してください');
      return false;
    }

    if (leadTime.value && parseInt(leadTime.value) <= 0) {
      showError('リードタイムは1以上の値を入力してください');
      return false;
    }

    if (orderPoint.value && isNaN(parseInt(orderPoint.value))) {
      showError('発注点は数値を入力してください');
      return false;
    }

    return true;
  }

  // 発注量計算処理
  async function calculateOrderQuantity() {
    if (!validateInputs()) return;

    const storeSelect = container.querySelector('#store-select');
    const categorySelect = container.querySelector('#category-select');
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 1;
    const orderPoint = parseInt(container.querySelector('#order-point').value) || 0;
    const orderCycle = parseInt(container.querySelector('#order-cycle').value) || 7;

    try {
      // 需要予測データ取得
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      const products = await window.aivicApi.list(2); // 商品マスタ
      const stores = await window.aivicApi.list(1); // 店舗マスタ

      if (!forecasts || !products || !stores) {
        showError('データの取得に失敗しました');
        return;
      }

      const selectedStores = Array.from(storeSelect.selectedOptions).map(opt => opt.value);
      const results = [];

      for (const storeId of selectedStores) {
        const store = stores.find(s => s.店舗ID === storeId);
        if (!store) continue;

        const storeForecasts = forecasts.filter(f => 
          f.店舗ID === storeId && 
          f.予測対象日 >= periodStart.value && 
          f.予測対象日 <= periodEnd.value
        );

        for (const forecast of storeForecasts) {
          const product = products.find(p => p.商品ID === forecast.商品ID);
          if (!product) continue;

          // カテゴリフィルタ
          if (categorySelect.value && product.商品カテゴリID !== categorySelect.value) continue;

          const predictedDemand = forecast.予測数量 || 0;
          const currentStock = Math.floor(Math.random() * 100); // 実際は在庫データから取得

          // 発注量計算ロジック
          let recommendedOrder = 0;
          const totalDemand = predictedDemand * orderCycle;
          const requiredStock = totalDemand + safetyStock;

          if (currentStock < orderPoint || currentStock < requiredStock) {
            recommendedOrder = Math.max(0, requiredStock - currentStock);
            // 発注単位で調整
            const orderUnit = product.発注単位 || 1;
            recommendedOrder = Math.ceil(recommendedOrder / orderUnit) * orderUnit;
          }

          const orderAmount = recommendedOrder * (product.単価 || 0);
          const deliveryDate = new Date();
          deliveryDate.setDate(deliveryDate.getDate() + leadTime);

          results.push({
            id: `${storeId}-${forecast.商品ID}-${Date.now()}`,
            店舗名: store.店舗名,
            商品名: product.商品名,
            商品コード: product.商品コード,
            現在在庫数: currentStock,
            予測需要量: predictedDemand,
            安全在庫数: safetyStock,
            発注点: orderPoint,
            推奨発注量: recommendedOrder,
            発注金額: orderAmount,
            納期予定日: deliveryDate.toISOString().split('T')[0],
            店舗ID: storeId,
            商品ID: forecast.商品ID,
            需要予測結果ID: forecast.予測結果ID
          });
        }
      }

      calculationResults = results;
      renderResults(results);

      // 需要予測結果表示更新
      const forecastDisplay = container.querySelector('#forecast-display');
      const totalDemand = results.reduce((sum, r) => sum + r.予測需要量, 0);
      forecastDisplay.innerHTML = `
        <h4>需要予測サマリー</h4>
        <p>対象商品数: ${results.length}件</p>
        <p>総予測需要量: ${totalDemand.toLocaleString()}個</p>
        <p>計算期間: ${periodStart.value} ～ ${periodEnd.value}</p>
      `;

      // 在庫状況表示更新
      const inventoryDisplay = container.querySelector('#inventory-display');
      const totalStock = results.reduce((sum, r) => sum + r.現在在庫数, 0);
      const totalOrderAmount = results.reduce((sum, r) => sum + r.発注金額, 0);
      inventoryDisplay.innerHTML = `
        <h4>在庫状況サマリー</h4>
        <p>総在庫数: ${totalStock.toLocaleString()}個</p>
        <p>推奨発注総額: ${totalOrderAmount.toLocaleString()}円</p>
        <p>発注対象商品数: ${results.filter(r => r.推奨発注量 > 0).length}件</p>
      `;

      showSuccess(`発注量計算が完了しました。${results.length}件の結果を表示しています。`);

    } catch (error) {
      console.error('計算エラー:', error);
      showError('発注量計算中にエラーが発生しました');
    }
  }

  // 発注データ生成
  async function generateOrderData() {
    const checkedResults = calculationResults.filter((_, index) => {
      const checkbox = container.querySelector(`input[data-id="${calculationResults[index].id}"]`);
      return checkbox && checkbox.checked;
    });

    if (checkedResults.length === 0) {
      showError('発注データを生成する商品を選択してください');
      return;
    }

    if (!confirm(`${checkedResults.length}件の発注データを生成しますか？`)) {
      return;
    }

    try {
      const orderData = checkedResults.map(result => ({
        店舗ID: result.店舗ID,
        商品ID: result.商品ID,
        需要予測結果ID: result.需要予測結果ID,
        発注日: new Date().toISOString(),
        納期予定日: new Date(result.納期予定日).toISOString(),
        発注数量: result.推奨発注量,
        予測数量: result.予測需要量,
        発注単価: Math.floor(result.発注金額 / result.推奨発注量) || 0,
        発注金額: result.発注金額,
        発注方法: 'AI自動発注',
        発注ステータス: '発注済',
        仕入先ID: 'dummy-supplier-id',
        発注理由: 'AI需要予測に基づく自動発注',
        自動発注フラグ: true,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      }));

      // 発注データを一括保存
      let successCount = 0;
      for (const order of orderData) {
        const saved = await window.aivicApi.save(9, order); // 発注データテーブル
        if (saved) successCount++;
      }

      showSuccess(`${successCount}件の発注データを生成しました`);

      // 発注管理画面に遷移
      setTimeout(() => {
        window.showScreen('scr-1778591852463');
      }, 2000);

    } catch (error) {
      console.error('発注データ生成エラー:', error);
      showError('発注データの生成に失敗しました');
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (calculationResults.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['店舗名', '商品名', '商品コード', '現在在庫数', '予測需要量', '安全在庫数', '発注点', '推奨発注量', '発注金額', '納期予定日'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...calculationResults.map(row => [
        `"${row.店舗名}"`,
        `"${row.商品名}"`,
        `"${row.商品コード}"`,
        row.現在在庫数,
        row.予測需要量,
        row.安全在庫数,
        row.発注点,
        row.推奨発注量,
        row.発注金額,
        `"${row.納期予定日}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();
  renderResults([]);

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  const nextWeek = new Date();
  nextWeek.setDate(nextWeek.getDate() + 7);
  container.querySelector('#period-start').value = today;
  container.querySelector('#period-end').value = nextWeek.toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  container.querySelector('#btn-bulk-calculate').addEventListener('click', calculateOrderQuantity);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelectorAll('.input').forEach(input => {
      if (input.type === 'checkbox') {
        input.checked = false;
      } else {
        input.value = '';
      }
    });
    calculationResults = [];
    renderResults([]);
    container.querySelector('#forecast-display').innerHTML = '<p class="muted">計算実行後に需要予測結果が表示されます</p>';
    container.querySelector('#inventory-display').innerHTML = '<p class="muted">店舗・商品選択後に在庫状況が表示されます</p>';
  });

  container.querySelector('#btn-search').addEventListener('click', () => {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    const filtered = calculationResults.filter(result => 
      result.商品名.toLowerCase().includes(keyword) ||
      result.商品コード.toLowerCase().includes(keyword) ||
      result.店舗名.toLowerCase().includes(keyword)
    );
    renderResults(filtered);
  });

  container.querySelector('#btn-generate-order').addEventListener('click', generateOrderData);

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.result-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この計算結果を削除しますか？')) return;
      const id = deleteBtn.dataset.id;
      calculationResults = calculationResults.filter(r => r.id !== id);
      renderResults(calculationResults);
      showSuccess('計算結果を削除しました');
      return;
    }

    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const id = editBtn.dataset.id;
      const result = calculationResults.find(r => r.id === id);
      if (result) {
        const newQuantity = prompt('推奨発注量を修正してください:', result.推奨発注量);
        if (newQuantity !== null && !isNaN(newQuantity)) {
          result.推奨発注量 = parseInt(newQuantity);
          result.発注金額 = result.推奨発注量 * (result.発注金額 / (result.推奨発注量 || 1));
          renderResults(calculationResults);
          showSuccess('発注量を修正しました');
        }
      }
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const resultCount = container.querySelector("#result-count");
  const noResults = container.querySelector("#no-results");
  const errorMessage = container.querySelector("#error-message");

  // 店舗マスタのインデックスを取得
  const storeTableIndex = tables.findIndex(t => t.tableName === "店舗マスタ");
  const productTableIndex = tables.findIndex(t => t.tableName === "商品マスタ");

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector("#store-select");
    if (storeTableIndex >= 0 && tables[storeTableIndex].records) {
      tables[storeTableIndex].records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement("option");
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況を判定
  function getStockStatus(currentStock, safetyStock) {
    if (!safetyStock) return "適正";
    const ratio = currentStock / safetyStock;
    if (ratio < 0.5) return "不足";
    if (ratio > 2.0) return "過剰";
    return "適正";
  }

  // 在庫状況のスタイルを取得
  function getStatusStyle(status) {
    switch (status) {
      case "不足":
        return "background: rgba(255, 106, 0, 0.1); color: #ff6a00; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      case "過剰":
        return "background: rgba(255, 193, 7, 0.1); color: #ffc107; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      default:
        return "background: rgba(40, 167, 69, 0.1); color: #28a745; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
    }
  }

  // 在庫データを生成（デモ用）
  function generateInventoryData(products, storeId) {
    if (!products || !storeId) return [];

    return products.filter(p => p.有効フラグ).map(product => {
      const currentStock = Math.floor(Math.random() * 200);
      const safetyStock = Math.floor(Math.random() * 50) + 10;
      const orderPoint = Math.floor(safetyStock * 1.5);
      const lastReceived = new Date(Date.now() - Math.floor(Math.random() * 30) * 24 * 60 * 60 * 1000);

      return {
        id: `${storeId}-${product.商品ID}`,
        商品コード: product.商品コード,
        商品名: product.商品名,
        現在在庫数: currentStock,
        安全在庫数: safetyStock,
        発注点: orderPoint,
        最終入荷日: lastReceived.toISOString().split('T')[0],
        在庫状況: getStockStatus(currentStock, safetyStock),
        商品カテゴリ: product.商品カテゴリID // カテゴリフィルタ用
      };
    });
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      resultCount.textContent = "0件";
      noResults.classList.remove("hidden");
      return;
    }

    noResults.classList.add("hidden");
    resultCount.textContent = `${rows.length}件`;

    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}">
        <td>${row.商品コード || ""}</td>
        <td>${row.商品名 || ""}</td>
        <td style="text-align: right;">${row.現在在庫数 || 0}</td>
        <td style="text-align: right;">${row.安全在庫数 || 0}</td>
        <td style="text-align: right;">${row.発注点 || 0}</td>
        <td>${row.最終入荷日 || ""}</td>
        <td><span style="${getStatusStyle(row.在庫状況)}">${row.在庫状況}</span></td>
      </tr>
    `).join("");
  }

  // 検索処理
  async function performSearch() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const productName = container.querySelector("#product-name-search").value.trim();
    const productCode = container.querySelector("#product-code-search").value.trim();
    const stockStatus = container.querySelector("#stock-status-filter").value;

    // バリデーション
    if (!storeId) {
      showError("店舗を選択してください。");
      return;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|javascript:|on\w+\s*=|['";]|DROP\s+TABLE|SELECT\s+\*|INSERT\s+INTO|DELETE\s+FROM/i;
    if (dangerousChars.test(productName) || dangerousChars.test(productCode)) {
      showError("不正な文字が含まれています。");
      return;
    }

    // 商品コード形式チェック（英数字とハイフンのみ、最大20文字）
    if (productCode && !/^[A-Za-z0-9\-]{1,20}$/.test(productCode)) {
      showError("商品コードは英数字とハイフン、最大20文字で入力してください。");
      return;
    }

    try {
      // 商品マスタを取得
      const products = await window.aivicApi.list(productTableIndex);
      if (!products) {
        showError("商品データの取得に失敗しました。");
        return;
      }

      // 在庫データを生成
      let inventoryData = generateInventoryData(products, storeId);

      // フィルタリング
      if (category) {
        inventoryData = inventoryData.filter(item => {
          const product = products.find(p => p.商品コード === item.商品コード);
          return product && product.商品カテゴリID === category;
        });
      }

      if (productName) {
        inventoryData = inventoryData.filter(item => 
          item.商品名.toLowerCase().includes(productName.toLowerCase())
        );
      }

      if (productCode) {
        inventoryData = inventoryData.filter(item => 
          item.商品コード.toLowerCase().includes(productCode.toLowerCase())
        );
      }

      if (stockStatus) {
        inventoryData = inventoryData.filter(item => item.在庫状況 === stockStatus);
      }

      renderRows(inventoryData);

    } catch (error) {
      showError("検索処理中にエラーが発生しました。");
      console.error("Search error:", error);
    }
  }

  // CSVエクスポート
  function exportCSV() {
    const storeId = container.querySelector("#store-select").value;
    if (!storeId) {
      showError("店舗を選択してからエクスポートしてください。");
      return;
    }

    window.aivicApi.list(productTableIndex).then(products => {
      if (!products) return;

      const inventoryData = generateInventoryData(products, storeId);

      const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "発注点", "最終入荷日", "在庫状況"];
      const csvContent = [
        headers.join(","),
        ...inventoryData.map(row => [
          `"${row.商品コード || ""}"`,
          `"${row.商品名 || ""}"`,
          row.現在在庫数 || 0,
          row.安全在庫数 || 0,
          row.発注点 || 0,
          `"${row.最終入荷日 || ""}"`,
          `"${row.在庫状況 || ""}"`
        ].join(","))
      ].join("\n");

      const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `inventory_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 検索条件クリア
  function clearSearchConditions() {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#product-name-search").value = "";
    container.querySelector("#product-code-search").value = "";
    container.querySelector("#stock-status-filter").value = "";
    renderRows([]);
  }

  // 初期化
  initStoreOptions();
  renderRows([]);

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // Enterキーで検索
  container.querySelector("#product-name-search").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });

  container.querySelector("#product-code-search").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#order-tbody");
  const errorMessage = container.querySelector("#error-message");
  const storeSelect = container.querySelector("#select-store");
  const orderDateInput = container.querySelector("#input-order-date");
  const categorySelect = container.querySelector("#select-category");
  const totalAmountSpan = container.querySelector("#total-amount");
  const totalItemsSpan = container.querySelector("#total-items");

  let currentOrderData = [];
  let storeData = [];
  let productData = [];
  let forecastData = [];

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 合計金額計算
  function calculateTotals() {
    let totalAmount = 0;
    let totalItems = 0;

    const quantityInputs = container.querySelectorAll(".order-quantity-input");
    quantityInputs.forEach(input => {
      const quantity = parseInt(input.value) || 0;
      if (quantity > 0) {
        const unitPrice = parseInt(input.dataset.unitPrice) || 0;
        totalAmount += quantity * unitPrice;
        totalItems++;
      }
    });

    totalAmountSpan.textContent = `¥${totalAmount.toLocaleString()}`;
    totalItemsSpan.textContent = `${totalItems}件`;
  }

  // 発注データ描画
  function renderOrderData(data) {
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      calculateTotals();
      return;
    }

    tbody.innerHTML = data.map(item => {
      const product = productData.find(p => p.商品ID === item.商品ID) || {};
      const forecast = forecastData.find(f => f.商品ID === item.商品ID) || {};
      const orderAmount = (item.発注数量 || 0) * (item.発注単価 || 0);

      return `
        <tr data-id="${item.発注ID || ''}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${product.商品カテゴリ || ''}</td>
          <td class="quantity-cell">${forecast.予測数量 || 0}</td>
          <td class="quantity-cell">${forecast.推奨発注数量 || 0}</td>
          <td class="quantity-cell">${item.現在在庫数量 || 0}</td>
          <td>
            <input type="number" 
                   class="input order-quantity-input" 
                   value="${item.発注数量 || 0}"
                   min="0"
                   max="999999"
                   data-product-id="${item.商品ID}"
                   data-unit-price="${item.発注単価 || 0}">
          </td>
          <td class="amount-cell">¥${(item.発注単価 || 0).toLocaleString()}</td>
          <td class="amount-cell">¥${orderAmount.toLocaleString()}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${item.発注ID || ''}">編集</button>
          </td>
        </tr>
      `;
    }).join("");

    calculateTotals();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeData = stores;
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join("");
      }

      // 商品データ読み込み
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productData = products;
      }

      // 需要予測データ読み込み
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      if (forecasts) {
        forecastData = forecasts;
      }

      // 発注データ読み込み
      const orders = await window.aivicApi.list(9); // 発注データ
      if (orders) {
        currentOrderData = orders;
        renderOrderData(orders);
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
      showError("データの読み込みに失敗しました");
    }
  }

  // 今日の日付を設定
  const today = new Date();
  orderDateInput.value = today.toISOString().split('T')[0];

  // 表示ボタン
  container.querySelector("#btn-display").addEventListener("click", async () => {
    const storeId = storeSelect.value;
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    try {
      const orders = await window.aivicApi.list(9);
      if (orders) {
        const filteredOrders = orders.filter(order => order.店舗ID === storeId);

        // カテゴリフィルター適用
        const selectedCategory = categorySelect.value;
        if (selectedCategory) {
          const filteredByCategory = filteredOrders.filter(order => {
            const product = productData.find(p => p.商品ID === order.商品ID);
            return product && product.商品カテゴリ === selectedCategory;
          });
          renderOrderData(filteredByCategory);
        } else {
          renderOrderData(filteredOrders);
        }
      }
    } catch (error) {
      showError("発注データの取得に失敗しました");
    }
  });

  // 予測結果更新ボタン
  container.querySelector("#btn-update-forecast").addEventListener("click", async () => {
    const orderDate = orderDateInput.value;
    const storeId = storeSelect.value;

    if (!orderDate) {
      showError("発注日付を選択してください");
      return;
    }

    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    // 過去日付チェック
    const selectedDate = new Date(orderDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (selectedDate < today) {
      showError("発注日付には本日以降の日付を選択してください");
      return;
    }

    try {
      // 需要予測データを再取得
      const forecasts = await window.aivicApi.list(8);
      if (forecasts) {
        forecastData = forecasts;
        // 現在表示中のデータを再描画
        const currentData = Array.from(tbody.querySelectorAll("tr")).map(tr => {
          const productId = tr.querySelector(".order-quantity-input")?.dataset.productId;
          return currentOrderData.find(order => order.商品ID === productId);
        }).filter(Boolean);
        renderOrderData(currentData);
      }
    } catch (error) {
      showError("予測結果の更新に失敗しました");
    }
  });

  // 推奨発注数量で一括入力
  container.querySelector("#btn-bulk-recommend").addEventListener("click", () => {
    if (!confirm("推奨発注数量で一括入力しますか？")) return;

    const quantityInputs = container.querySelectorAll(".order-quantity-input");
    quantityInputs.forEach(input => {
      const productId = input.dataset.productId;
      const forecast = forecastData.find(f => f.商品ID === productId);
      if (forecast && forecast.推奨発注数量) {
        input.value = forecast.推奨発注数量;
      }
    });
    calculateTotals();
  });

  // 承認実行
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    const storeId = storeSelect.value;
    const orderDate = orderDateInput.value;

    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    if (!orderDate) {
      showError("発注日付を選択してください");
      return;
    }

    // 過去日付チェック
    const selectedDate = new Date(orderDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (selectedDate < today) {
      showError("発注日付には本日以降の日付を選択してください");
      return;
    }

    const quantityInputs = container.querySelectorAll(".order-quantity-input");
    let hasValidOrder = false;
    let hasError = false;

    // バリデーション
    for (const input of quantityInputs) {
      const value = input.value.trim();
      const quantity = parseInt(value);

      if (value === "") {
        showError("発注数量を入力してください");
        hasError = true;
        break;
      }

      if (isNaN(quantity)) {
        showError("発注数量は数値を入力してください");
        hasError = true;
        break;
      }

      if (quantity < 0) {
        showError("発注数量は正の値を入力してください");
        hasError = true;
        break;
      }

      if (quantity > 0) {
        hasValidOrder = true;
      }
    }

    if (hasError) return;

    if (!confirm("発注内容を承認して実行しますか？")) return;

    try {
      // 発注データを保存
      const promises = [];
      quantityInputs.forEach(input => {
        const quantity = parseInt(input.value) || 0;
        const productId = input.dataset.productId;
        const unitPrice = parseInt(input.dataset.unitPrice) || 0;

        if (quantity >= 0) { // 0でも承認可能
          const orderData = {
            店舗ID: storeId,
            商品ID: productId,
            発注日: orderDate,
            発注数量: quantity,
            発注単価: unitPrice,
            発注金額: quantity * unitPrice,
            発注方法: "手動発注",
            発注ステータス: "承認済み",
            自動発注フラグ: false,
            納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] // 3日後
          };
          promises.push(window.aivicApi.save(9, orderData));
        }
      });

      await Promise.all(promises);

      // 成功メッセージ表示（エラーメッセージ要素を流用）
      errorMessage.style.background = "rgba(0, 200, 0, 0.1)";
      errorMessage.style.borderColor = "#00c800";
      errorMessage.textContent = "発注が正常に承認されました";
      errorMessage.classList.remove("hidden");

      setTimeout(() => {
        errorMessage.classList.add("hidden");
        errorMessage.style.background = "rgba(255, 106, 0, 0.1)";
        errorMessage.style.borderColor = "#ff6a00";
      }, 3000);

      // データを再読み込み
      await loadInitialData();

    } catch (error) {
      showError("発注の承認に失敗しました");
    }
  });

  // 発注数量入力時の金額計算
  container.addEventListener("input", (e) => {
    if (e.target.classList.contains("order-quantity-input")) {
      calculateTotals();
    }
  });

  // 発注数量のバリデーション
  container.addEventListener("blur", (e) => {
    if (e.target.classList.contains("order-quantity-input")) {
      const value = e.target.value.trim();
      const quantity = parseInt(value);

      if (value !== "" && (isNaN(quantity) || quantity < 0)) {
        if (isNaN(quantity)) {
          showError("発注数量は数値を入力してください");
        } else if (quantity < 0) {
          showError("発注数量は正の値を入力してください");
        }
        e.target.focus();
      }
    }
  }, true);

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const orderId = editBtn.dataset.id;
      // 編集機能は発注管理画面に遷移
      window.showScreen("scr-1778591852463");
    }
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let currentSort = { field: 'accuracy', direction: 'desc' };
  let accuracyChart = null;
  let comparisonChart = null;

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-filter');
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeSelect.appendChild(option);
    });
  }

  // ランキングテーブルの再描画
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((item, index) => `
      <tr>
        <td>${index + 1}</td>
        <td>${item.店舗名 || '-'}</td>
        <td>${item.カテゴリ || '-'}</td>
        <td style="color: ${item.精度 >= 80 ? '#4ade80' : item.精度 >= 60 ? '#fbbf24' : '#ef4444'};">${item.精度}%</td>
        <td>${item.MAPE}%</td>
        <td>${item.RMSE}</td>
      </tr>
    `).join('');
  }

  // データソート
  function sortData(data, field, direction) {
    return [...data].sort((a, b) => {
      let aVal = a[field];
      let bVal = b[field];

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (direction === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });
  }

  // 予測精度推移グラフの描画
  function drawAccuracyChart() {
    const canvas = container.querySelector('#accuracy-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * devicePixelRatio;
    canvas.height = rect.height * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);

    const width = rect.width;
    const height = rect.height;

    // 背景をクリア
    ctx.clearRect(0, 0, width, height);

    // サンプルデータ
    const dates = ['1/10', '1/11', '1/12', '1/13', '1/14', '1/15', '1/16'];
    const accuracies = [82, 85, 83, 87, 84, 86, 85];

    const padding = 50;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Y軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const y = height - padding - (chartHeight * i / 5);
      const value = 60 + (i * 8);
      ctx.fillText(value + '%', padding - 10, y + 4);
    }

    // X軸ラベル
    ctx.textAlign = 'center';
    dates.forEach((date, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      ctx.fillText(date, x, height - padding + 20);
    });

    // データライン描画
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    accuracies.forEach((acc, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      const y = height - padding - ((acc - 60) / 40 * chartHeight);
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#3b82f6';
    accuracies.forEach((acc, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      const y = height - padding - ((acc - 60) / 40 * chartHeight);
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  // 予測vs実績比較チャートの描画
  function drawComparisonChart() {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * devicePixelRatio;
    canvas.height = rect.height * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);

    const width = rect.width;
    const height = rect.height;

    ctx.clearRect(0, 0, width, height);

    const dates = ['1/10', '1/11', '1/12', '1/13', '1/14', '1/15', '1/16'];
    const predicted = [120, 135, 128, 142, 138, 145, 140];
    const actual = [115, 140, 125, 145, 135, 148, 138];

    const padding = 50;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Y軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const y = height - padding - (chartHeight * i / 5);
      const value = 100 + (i * 20);
      ctx.fillText(value, padding - 10, y + 4);
    }

    // X軸ラベル
    ctx.textAlign = 'center';
    dates.forEach((date, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      ctx.fillText(date, x, height - padding + 20);
    });

    // 予測値ライン
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    predicted.forEach((val, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      const y = height - padding - ((val - 100) / 50 * chartHeight);
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 実績値ライン
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;
    ctx.beginPath();
    actual.forEach((val, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      const y = height - padding - ((val - 100) / 50 * chartHeight);
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(width - 150, 20, 15, 3);
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('予測値', width - 130, 25);

    ctx.fillStyle = '#ef4444';
    ctx.fillRect(width - 150, 40, 15, 3);
    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('実績値', width - 130, 45);
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // ローディング表示制御
  function showLoading(show) {
    const loading = container.querySelector('#loading');
    if (show) {
      loading.classList.remove('hidden');
    } else {
      loading.classList.add('hidden');
    }
  }

  // データ読み込み
  async function loadData() {
    try {
      showLoading(true);

      // 需要予測結果データを取得
      const predictionData = await window.aivicApi.list(8);
      if (predictionData) {
        // サンプルデータで精度ランキングを生成
        const rankingData = [
          { 店舗名: '店舗A', カテゴリ: '食品', 精度: 87, MAPE: 13.2, RMSE: 11.5 },
          { 店舗名: '店舗B', カテゴリ: '飲料', 精度: 82, MAPE: 18.1, RMSE: 14.2 },
          { 店舗名: '店舗C', カテゴリ: '日用品', 精度: 75, MAPE: 25.3, RMSE: 18.7 },
          { 店舗名: '店舗D', カテゴリ: '食品', 精度: 91, MAPE: 9.2, RMSE: 8.3 },
          { 店舗名: '店舗E', カテゴリ: '飲料', 精度: 78, MAPE: 22.1, RMSE: 16.9 }
        ];

        currentData = sortData(rankingData, currentSort.field, currentSort.direction);
        renderRankingTable(currentData);
      }
    } catch (error) {
      showError('データの読み込みに失敗しました: ' + error.message);
    } finally {
      showLoading(false);
    }
  }

  // フィルター適用
  async function applyFilters() {
    const period = container.querySelector('#period-filter').value;
    const storeId = container.querySelector('#store-filter').value;
    const category = container.querySelector('#category-filter').value;

    try {
      showLoading(true);

      // フィルター条件に基づいてデータを絞り込み
      let filteredData = [...currentData];

      if (storeId) {
        const store = tables[1]?.records?.find(s => s.店舗ID === storeId);
        if (store) {
          filteredData = filteredData.filter(item => item.店舗名 === store.店舗名);
        } else {
          showError('指定された店舗が見つかりません');
          return;
        }
      }

      if (category) {
        filteredData = filteredData.filter(item => item.カテゴリ === category);
      }

      if (filteredData.length === 0) {
        showError('指定された期間にはデータが存在しません');
      }

      renderRankingTable(filteredData);

    } catch (error) {
      showError('フィルターの適用に失敗しました: ' + error.message);
    } finally {
      showLoading(false);
    }
  }

  // レポート出力
  async function exportReport() {
    try {
      showLoading(true);

      // CSVデータ生成
      const headers = ['順位', '店舗名', 'カテゴリ', '精度(%)', 'MAPE(%)', 'RMSE'];
      const csvData = [
        headers.join(','),
        ...currentData.map((item, index) => [
          index + 1,
          item.店舗名,
          item.カテゴリ,
          item.精度,
          item.MAPE,
          item.RMSE
        ].join(','))
      ].join('\n');

      // ダウンロード
      const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = '予測精度レポート_' + new Date().toISOString().split('T')[0] + '.csv';
      link.click();

    } catch (error) {
      showError('レポート出力に失敗しました: ' + error.message);
    } finally {
      showLoading(false);
    }
  }

  // 初期化
  initStoreOptions();
  loadData();

  // グラフ描画（初期化後に実行）
  setTimeout(() => {
    drawAccuracyChart();
    drawComparisonChart();
  }, 100);

  // イベントリスナー
  container.querySelector('#btn-apply-filters').addEventListener('click', applyFilters);
  container.querySelector('#btn-export-report').addEventListener('click', exportReport);

  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591822586'); // 相関分析・比較分析画面
  });

  // テーブルソート
  container.addEventListener('click', (e) => {
    const sortBtn = e.target.closest('th[data-sort]');
    if (sortBtn) {
      const field = sortBtn.dataset.sort;
      const fieldMap = {
        'rank': '精度',
        'store': '店舗名',
        'category': 'カテゴリ',
        'accuracy': '精度',
        'mape': 'MAPE',
        'rmse': 'RMSE'
      };

      if (currentSort.field === fieldMap[field]) {
        currentSort.direction = currentSort.direction === 'asc' ? 'desc' : 'asc';
      } else {
        currentSort.field = fieldMap[field];
        currentSort.direction = 'desc';
      }

      const sortedData = sortData(currentData, currentSort.field, currentSort.direction);
      renderRankingTable(sortedData);
    }
  });

  // グラフ期間切り替え
  container.querySelector('#btn-daily').addEventListener('click', () => {
    drawAccuracyChart();
    drawComparisonChart();
  });

  container.querySelector('#btn-weekly').addEventListener('click', () => {
    drawAccuracyChart();
    drawComparisonChart();
  });

  container.querySelector('#btn-monthly').addEventListener('click', () => {
    drawAccuracyChart();
    drawComparisonChart();
  });

  // ウィンドウリサイズ時のグラフ再描画
  window.addEventListener('resize', () => {
    setTimeout(() => {
      drawAccuracyChart();
      drawComparisonChart();
    }, 100);
  });
}

