    const stores = tables.find(t => t.tableName === "店舗マスタ")?.records || [];

    storeCheckboxes.innerHTML = stores.map(store => `
      <label>
        <input type="checkbox" class="store-checkbox" value="${store.店舗ID}">
        ${store.店舗名}
      </label>
    `).join("");
  }

  // 予測精度指標の表示
  function displayAccuracyMetrics(mape, rmse, r2, executionTime) {
    container.querySelector("#mape-value").textContent = mape !== null && mape !== undefined ? 
      (mape <= 0 || mape >= 100 ? "N/A" : mape.toFixed(2)) : "N/A";
    container.querySelector("#rmse-value").textContent = rmse !== null && rmse !== undefined ? 
      (rmse < 0 ? "算出不可" : rmse.toFixed(2)) : "N/A";
    container.querySelector("#r2-value").textContent = r2 !== null && r2 !== undefined ? 
      (r2 < 0 || r2 > 1 ? "N/A" : r2.toFixed(3)) : "N/A";
    container.querySelector("#final-execution-time").textContent = executionTime || "0";
  }

  // 実績値vs予測値グラフの描画
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスサイズを設定
    canvas.width = 800;
    canvas.height = 400;

    // 背景をクリア
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ（実際の実装では API から取得）
    const actualData = [120, 135, 98, 156, 142, 118, 167, 189, 145, 132];
    const predictedData = [115, 140, 102, 150, 138, 125, 160, 185, 148, 128];
    const labels = ['1日', '2日', '3日', '4日', '5日', '6日', '7日', '8日', '9日', '10日'];

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データの最大値・最小値を計算
    const allData = [...actualData, ...predictedData];
    const maxValue = Math.max(...allData);
    const minValue = Math.min(...allData);
    const valueRange = maxValue - minValue;

    // 実績値の線を描画
    ctx.strokeStyle = '#51cf66';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (actualData.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((actualData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値の線を描画
    ctx.strokeStyle = '#ff6b6b';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (i / (predictedData.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((predictedData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // 凡例の描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px sans-serif';
    ctx.fillText('実績値', canvas.width - 150, 30);
    ctx.fillText('予測値', canvas.width - 150, 50);

    ctx.strokeStyle = '#51cf66';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 25);
    ctx.lineTo(canvas.width - 155, 25);
    ctx.stroke();

    ctx.strokeStyle = '#ff6b6b';
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 45);
    ctx.lineTo(canvas.width - 155, 45);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // モデルパラメータの表示
  function displayModelParameters() {
    const tbody = container.querySelector("#params-tbody");
    const sampleParams = [
      { name: "学習率", value: "0.001", description: "モデルの学習速度を制御" },
      { name: "隠れ層数", value: "3", description: "ニューラルネットワークの層数" },
      { name: "バッチサイズ", value: "32", description: "一度に処理するデータ数" },
      { name: "エポック数", value: "100", description: "学習の反復回数" },
      { name: "正則化係数", value: "0.01", description: "過学習を防ぐパラメータ" }
    ];

    tbody.innerHTML = sampleParams.map(param => `
      <tr>
        <td>${param.name}</td>
        <td>${param.value}</td>
        <td class="muted">${param.description}</td>
      </tr>
    `).join("");
  }

  // バリデーション関数
  function validateTestSettings() {
    const model = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const category = container.querySelector("#category-select").value;
    const selectedStores = container.querySelectorAll(".store-checkbox:checked");
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');

    if (!model) {
      showError("予測モデルが選択されていません");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください");
      return false;
    }

    if (new Date(endDate) < new Date(startDate)) {
      showError("終了日は開始日より後の日付を設定してください");
      return false;
    }

    if (selectedStores.length === 0) {
      showError("対象店舗を選択してください");
      return false;
    }

    if (!category) {
      showError("商品カテゴリが未選択です");
      return false;
    }

    if (!selectedDataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    return true;
  }

  // エラーメッセージ表示
  function showError(message) {
    const existingError = container.querySelector(".error-message");
    if (existingError) existingError.remove();

    const errorDiv = document.createElement("div");
    errorDiv.className = "error-message";
    errorDiv.textContent = message;
    container.querySelector(".test-settings").appendChild(errorDiv);

    setTimeout(() => errorDiv.remove(), 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const existingSuccess = container.querySelector(".success-message");
    if (existingSuccess) existingSuccess.remove();

    const successDiv = document.createElement("div");
    successDiv.className = "success-message";
    successDiv.textContent = message;
    container.querySelector(".test-settings").appendChild(successDiv);

    setTimeout(() => successDiv.remove(), 5000);
  }

  // テスト実行のシミュレーション
  function executeModelTest() {
    if (!validateTestSettings()) return;

    const progressCard = container.querySelector("#test-progress");
    const resultsCard = container.querySelector("#test-results");
    const progressFill = container.querySelector("#progress-fill");
    const progressText = container.querySelector("#progress-text");
    const executionTimeSpan = container.querySelector("#execution-time");

    // プログレス表示
    progressCard.classList.remove("hidden");
    resultsCard.classList.add("hidden");

    executionStartTime = Date.now();
    let progress = 0;

    testExecutionTimer = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 100) progress = 100;

      progressFill.style.width = progress + "%";
      const elapsed = Math.floor((Date.now() - executionStartTime) / 1000);
      executionTimeSpan.textContent = elapsed;

      if (progress < 30) {
        progressText.textContent = "データを読み込み中...";
      } else if (progress < 60) {
        progressText.textContent = "モデルを実行中...";
      } else if (progress < 90) {
        progressText.textContent = "結果を計算中...";
      } else {
        progressText.textContent = "テストを完了中...";
      }

      if (progress >= 100) {
        clearInterval(testExecutionTimer);
        const finalTime = Math.floor((Date.now() - executionStartTime) / 1000);

        // 結果表示
        setTimeout(() => {
          progressCard.classList.add("hidden");
          resultsCard.classList.remove("hidden");

          // サンプル結果データ
          const mape = 12.5 + Math.random() * 10;
          const rmse = 15.2 + Math.random() * 5;
          const r2 = 0.85 + Math.random() * 0.1;

          displayAccuracyMetrics(mape, rmse, r2, finalTime);
          drawComparisonChart();
          displayModelParameters();

          // テスト履歴に追加
          const testResult = {
            予測モデルバージョン: container.querySelector("#model-select").value,
            分析期間開始日: container.querySelector("#start-date").value,
            分析期間終了日: container.querySelector("#end-date").value,
            サンプル数: container.querySelectorAll(".store-checkbox:checked").length,
            相関係数: (mape / 100).toString(),
            処理時間秒: finalTime,
            処理ステータス: "成功",
            作成日時: new Date().toISOString()
          };

          window.aivicApi.save(8, testResult).then(() => {
            window.aivicApi.list(8).then(renderTestHistory);
            showSuccess("モデルテストが正常に完了しました");
          });

        }, 1000);
      }
    }, 200);
  }

  // CSVエクスポート機能
  function exportTestResults() {
    const model = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    if (!model) {
      showError("エクスポートするテスト結果がありません");
      return;
    }

    const csvData = [
      ["項目", "値"],
      ["テスト実行日時", new Date().toLocaleString()],
      ["モデル名", model],
      ["テスト期間", `${startDate} - ${endDate}`],
      ["MAPE", container.querySelector("#mape-value").textContent + "%"],
      ["RMSE", container.querySelector("#rmse-value").textContent],
      ["決定係数(R²)", container.querySelector("#r2-value").textContent],
      ["実行時間", container.querySelector("#final-execution-time").textContent + "秒"]
    ];

    const csvContent = "\uFEFF" + csvData.map(row => 
      row.map(field => `"${field}"`).join(",")
    ).join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `model_test_results_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();

    showSuccess("テスト結果をエクスポートしました");
  }

  // 初期化
  renderStoreCheckboxes();

  // 相関分析結果テーブルからテスト履歴を表示
  const correlationTable = tables.find(t => t.tableName === "相関分析結果");
  if (correlationTable) {
    renderTestHistory(correlationTable.records || []);
  }

  // 全店舗選択チェックボックス
  container.querySelector("#select-all-stores").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".store-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", executeModelTest);

  // エクスポートボタン
  container.querySelector("#btn-export-results").addEventListener("click", exportTestResults);

  // 履歴テーブルのイベント処理
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(8, id);
      const rows = await window.aivicApi.list(8);
      if (rows) renderTestHistory(rows);
      showSuccess("テスト履歴を削除しました");
    }

    const viewBtn = e.target.closest(".view-detail-btn");
    if (viewBtn) {
      showSuccess("詳細表示機能は開発中です");
    }
  });

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#start-date").value = today;
  container.querySelector("#end-date").value = today;
}

function(container, apiUrl, tables) {
  let selectedStores = new Set();
  let currentModel = null;
  let isProcessing = false;

  // ログ追加関数
  function addLog(message, type = 'info') {
    const logDisplay = container.querySelector('#log-display');
    const timestamp = new Date().toLocaleString();
    const logEntry = document.createElement('div');
    logEntry.className = `log-entry ${type}`;
    logEntry.innerHTML = `<span class="timestamp">[${timestamp}]</span><span class="message">${message}</span>`;
    logDisplay.appendChild(logEntry);
    logDisplay.scrollTop = logDisplay.scrollHeight;
  }

  // 店舗一覧の描画
  function renderStores() {
    const storeList = container.querySelector('#store-list');
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];

    storeList.innerHTML = stores.map(store => `
      <label>
        <input type="checkbox" class="store-checkbox" data-store-id="${store.店舗ID}" value="${store.店舗ID}">
        ${store.店舗名} (${store.店舗コード})
      </label>
    `).join('');
  }

  // モデル一覧の描画
  function renderModels() {
    const modelSelect = container.querySelector('#select-model');
    // 需要予測結果テーブルから検証済みモデルを取得
    const predictions = tables.find(t => t.tableName === '需要予測結果')?.records || [];
    const models = [...new Set(predictions.map(p => p.予測モデルバージョン))].filter(Boolean);

    modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>' +
      models.map(model => `<option value="${model}">モデル ${model}</option>`).join('');
  }

  // モデル詳細情報の表示
  function showModelDetails(modelVersion) {
    const detailsSection = container.querySelector('#model-details');
    const predictions = tables.find(t => t.tableName === '需要予測結果')?.records || [];
    const modelPredictions = predictions.filter(p => p.予測モデルバージョン === modelVersion);

    if (modelPredictions.length > 0) {
      const sample = modelPredictions[0];
      const accuracy = modelPredictions.filter(p => p.予測精度).reduce((sum, p) => sum + (p.予測精度 || 0), 0) / modelPredictions.length || 0;

      container.querySelector('#detail-name').textContent = `AI需要予測モデル v${modelVersion}`;
      container.querySelector('#detail-version').textContent = modelVersion;
      container.querySelector('#detail-accuracy').textContent = `${accuracy.toFixed(1)}%`;
      container.querySelector('#detail-created').textContent = new Date(sample.作成日時).toLocaleDateString();

      detailsSection.classList.remove('hidden');

      // 検証結果の更新
      updateValidationResults(modelVersion, accuracy);
    }
  }

  // 検証結果の更新
  function updateValidationResults(modelVersion, accuracy) {
    const validationResults = container.querySelector('#validation-results');
    const isValid = accuracy >= 80; // 80%以上を合格とする

    validationResults.innerHTML = `
      <div class="validation-item">
        <span class="status ${isValid ? 'success' : 'error'}">${isValid ? '検証合格' : '検証不合格'}</span>
        <span>予測精度: ${accuracy.toFixed(1)}% ${isValid ? '(適用可能)' : '(精度不足)'}</span>
      </div>
      <div class="validation-item">
        <span class="status success">データ整合性</span>
        <span>モデルデータの整合性チェック完了</span>
      </div>
    `;
  }

  // 影響範囲の更新
  function updateImpactAnalysis() {
    const storeCount = selectedStores.size;
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const categories = [...new Set(products.map(p => p.商品カテゴリID))].length;
    const estimatedMinutes = Math.max(5, storeCount * 2); // 店舗数 × 2分（最低5分）

    container.querySelector('#impact-stores').textContent = `${storeCount}店舗`;
    container.querySelector('#impact-categories').textContent = `${categories}カテゴリ`;
    container.querySelector('#impact-duration').textContent = `約${estimatedMinutes}分`;

    const warningElement = container.querySelector('#impact-warning');
    if (storeCount >= 10) {
      warningElement.classList.remove('hidden');
    } else {
      warningElement.classList.add('hidden');
    }
  }

  // 適用実行の有効性チェック
  function updateDeployButtonState() {
    const deployBtn = container.querySelector('#btn-deploy');
    const modelSelected = container.querySelector('#select-model').value;
    const storesSelected = selectedStores.size > 0;
    const startDateTime = container.querySelector('#input-start-datetime').value;
    const retentionDays = parseInt(container.querySelector('#input-retention-days').value);

    const isValid = modelSelected && storesSelected && startDateTime && retentionDays > 0 && !isProcessing;
    deployBtn.disabled = !isValid;
  }

  // 進捗表示の更新
  function updateProgress(percentage, message) {
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');
    const progressSection = container.querySelector('#progress-section');

    progressSection.classList.remove('hidden');
    progressFill.style.width = `${percentage}%`;
    progressText.textContent = message;
  }

  // 適用処理のシミュレーション
  async function executeDeployment() {
    if (isProcessing) {
      addLog('既に適用処理が実行中です。処理完了後に再度実行してください。', 'error');
      return;
    }

    const modelVersion = container.querySelector('#select-model').value;
    const startDateTime = container.querySelector('#input-start-datetime').value;
    const retentionDays = parseInt(container.querySelector('#input-retention-days').value);
    const backupEnabled = container.querySelector('#backup-enabled').checked;

    // バリデーション
    if (!modelVersion) {
      addLog('適用対象のモデルが選択されていません', 'error');
      return;
    }

    if (selectedStores.size === 0) {
      addLog('店舗が選択されていない旨のエラーメッセージが表示されました', 'error');
      return;
    }

    if (new Date(startDateTime) < new Date()) {
      addLog('適用日時は現在日時以降を指定してください', 'error');
      return;
    }

    if (retentionDays <= 0) {
      addLog('保持期間に0日が設定されていることを警告します', 'warning');
      return;
    }

    isProcessing = true;
    updateDeployButtonState();

    try {
      addLog(`モデル ${modelVersion} の本番適用を開始します`, 'info');

      if (backupEnabled) {
        updateProgress(10, 'バックアップを作成中...');
        await new Promise(resolve => setTimeout(resolve, 1000));
        addLog('現行モデルのバックアップを作成しました', 'success');
      }

      updateProgress(30, 'モデルファイルを配信中...');
      await new Promise(resolve => setTimeout(resolve, 1500));
      addLog('モデルファイルの配信が完了しました', 'success');

      let progress = 30;
      const storeArray = Array.from(selectedStores);
      for (let i = 0; i < storeArray.length; i++) {
        const storeId = storeArray[i];
        const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
        const store = stores.find(s => s.店舗ID === storeId);

        progress = 30 + (i / storeArray.length) * 60;
        updateProgress(progress, `${store?.店舗名 || storeId} に適用中... (${i + 1}/${storeArray.length})`);

        await new Promise(resolve => setTimeout(resolve, 500));
        addLog(`${store?.店舗名 || storeId} への適用が完了しました`, 'success');
      }

      updateProgress(95, '最終検証中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      updateProgress(100, '適用完了');
      addLog(`全${selectedStores.size}店舗への適用が正常に完了しました`, 'success');
      addLog(`保持期間: ${retentionDays}日で設定されました`, 'info');

      // ロールバックボタンを有効化
      container.querySelector('#btn-rollback').disabled = false;

    } catch (error) {
      addLog(`適用処理中にエラーが発生しました: ${error.message}`, 'error');
      updateProgress(0, 'エラーが発生しました');
    } finally {
      isProcessing = false;
      updateDeployButtonState();
    }
  }

  // ロールバック処理
  async function executeRollback() {
    if (!container.querySelector('#btn-rollback').disabled) {
      if (!confirm('モデルをロールバックしますか？この操作は元に戻せません。')) {
        return;
      }

      addLog('ロールバック処理を開始します', 'info');
      updateProgress(0, 'ロールバック準備中...');

      try {
        updateProgress(25, 'バックアップモデルを復元中...');
        await new Promise(resolve => setTimeout(resolve, 1000));

        updateProgress(75, '各店舗に配信中...');
        await new Promise(resolve => setTimeout(resolve, 1500));

        updateProgress(100, 'ロールバック完了');
        addLog('ロールバック処理が正常に完了しました', 'success');

        container.querySelector('#btn-rollback').disabled = true;
      } catch (error) {
        addLog(`ロールバック処理中にエラーが発生しました: ${error.message}`, 'error');
      }
    } else {
      addLog('適用前のため、ロールバックできません', 'error');
    }
  }

  // 初期化
  renderStores();
  renderModels();

  // 現在日時を適用開始日時のデフォルトに設定
  const now = new Date();
  now.setMinutes(now.getMinutes() + 10); // 10分後をデフォルトに
  container.querySelector('#input-start-datetime').value = now.toISOString().slice(0, 16);

  // イベントリスナー
  container.querySelector('#select-model').addEventListener('change', (e) => {
    if (e.target.value) {
      currentModel = e.target.value;
      showModelDetails(e.target.value);
      addLog(`モデル ${e.target.value} が選択されました`, 'info');
    } else {
      container.querySelector('#model-details').classList.add('hidden');
      currentModel = null;
    }
    updateDeployButtonState();
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedStores.add(cb.dataset.storeId);
      } else {
        selectedStores.delete(cb.dataset.storeId);
      }
    });

    container.querySelector('#selected-store-count').textContent = selectedStores.size;
    updateImpactAnalysis();
    updateDeployButtonState();

    if (e.target.checked) {
      addLog(`全店舗が選択されました (${selectedStores.size}店舗)`, 'info');
    } else {
      addLog('全店舗の選択が解除されました', 'info');
    }
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      if (e.target.checked) {
        selectedStores.add(e.target.dataset.storeId);
      } else {
        selectedStores.delete(e.target.dataset.storeId);
        container.querySelector('#select-all-stores').checked = false;
      }

      container.querySelector('#selected-store-count').textContent = selectedStores.size;
      updateImpactAnalysis();
      updateDeployButtonState();
    }
  });

  container.querySelector('#input-start-datetime').addEventListener('change', updateDeployButtonState);
  container.querySelector('#input-retention-days').addEventListener('input', updateDeployButtonState);
  container.querySelector('#backup-enabled').addEventListener('change', updateDeployButtonState);

  container.querySelector('#btn-deploy').addEventListener('click', executeDeployment);
  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // 初期状態の更新
  updateImpactAnalysis();
  updateDeployButtonState();
}
